// ===== AR Geodet — REGISTR NÁSTROJŮ: jeden záznam na nástroj (ODPOJITELNÁ vrstva) =
// PROBLÉM, KTERÝ TENHLE SOUBOR ŘEŠÍ: appka má ~70 nástrojů a co o každém z nich
// platí, bylo rozepsané v ŠESTI ručních tabulkách v pěti různých souborech —
// kategorie v mřížce a synonyma pro hledání (field-tools.js), sloveso a popisek
// v seznamu úkonů (nastroje-ukony.js), návod pod „?“ (tools-plus.js), základní
// sada a typy práce (tools-simple.js), příznak „bez sítě neudělá nic“
// (offline-sbal.js). Nový nástroj se musel dopsat do všech šesti a NIC to
// nekontrolovalo — takže se to opakovaně nedopsalo:
//   • Kompas chyběl ve slovesech i v základní sadě → uživatel ho nenašel,
//   • Kontrola vrstvy a Metr v kameře padaly do záchytného „Další nástroje“,
//   • DronView měl návod zapsaný pod klíčem `openDronView`, ale dlaždice se jmenuje
//     `dronview` — takže se u ní „?“ vůbec neukázalo a offline se neodsunula
//     (příznak `net` visel na tomtéž špatném klíči). Při stěhování sem opraveno,
//   • 19 nástrojů nemělo synonyma, takže se nedaly najít hledáním. Doplněna.
//
// ŘEŠENÍ: tady je JEDEN ZÁZNAM NA NÁSTROJ a ostatní moduly si z něj berou, co
// potřebují (AGReg.groups(), AGReg.help(), AGReg.aliases(), AGReg.cat(), …).
// Přidat nástroj = přidat sem jeden řádek. Že se na něco zapomnělo, hlásí
// scripts/check_tools_registry.py (běží v CI).
//
// CO SEM NEPATŘÍ: samotné chování nástroje. Modul se dál registruje sám přes
// window.agRegisterFieldTool({id,label,icon,onClick}) a zůstává odpojitelný —
// registr je jen POPIS (kam patří, jak se hledá, co říká návod), ne kód.
//
// KLÍČ (`k`) je tentýž, jaký po dlaždici čte zbytek appky: `data-tool` u dlaždic
// vyrobených modulem, nebo název otevírací funkce z `onclick` u statických
// dlaždic v index.html (openMeasureModal, startAreaMode…).
//
// POLE ZÁZNAMU
//   k     klíč dlaždice (povinný)
//   cat   kategorie v mřížce Nástrojů; statické dlaždice ji mají z index.html
//   verb  sloveso = skupina v seznamu úkonů; bez něj spadne do „Další nástroje“
//   vl    popisek v seznamu úkonů („Vzdálenost a převýšení mezi body“)
//   vh    upřesnění pod popiskem (šedě, menším písmem)
//   keys  synonyma pro hledání, BEZ DIAKRITIKY a malými písmeny
//   help  { t: titulek, h: HTML návodu } — obsah bubliny „?“
//   net   1 = bez signálu neudělá nic (offline-sbal.js dlaždici odsune dolů)
//   base  1 = patří do základní sady jednoduchého režimu
//   hub   1 = dlaždici vyrábí jako rozcestník js/tools-hub.js (jen pro kontrolora)
//   notile 1 = není dlaždice v Nástrojích, návod se otevírá odjinud (jen pro kontrolora)
//   noverb 1 = záměrně bez slovesa, zůstává v „Dalších nástrojích“ (jen pro kontrolora)
//
// Odstranění: smaž js/tools-registry.js + řádek <script> v index.html. Appka
// pojede dál, ale nástroje přijdou o slovesa, návody, synonyma a typy prací —
// všechny moduly to snesou (mají prázdný registr jako platný stav).
// =================================================================================
(function () {
    'use strict';
    if (window.AGReg) return;

    // Pořadí sloves = pořadí skupin v seznamu úkonů (js/nastroje-ukony.js).
    var VERBS = ['Změřit', 'Určit nový bod', 'Vytyčit', 'Zaznamenat', 'Srovnat AR', 'Zjistit podmínky', 'Katastr a podklady', 'Před výjezdem', 'Firma a papíry', 'Příručka a výpočty'];

    // Typy práce pro jednoduchý režim (js/tools-simple.js). Pořadí = pořadí
    // v přepínači; `tools` je pořadí dlaždic v sekci „Pro tuto práci“.
    var PROFILES = [
        { id: 'univerzal', label: 'Univerzální', tools: [] },
        { id: 'vytycovani', label: 'Vytyčování', tools: ['openStakeoutModal', 'stakeout-line', 'offset-point', 'usadit-ar', 'agOpenCalibrate', 'kompas', 'rajon', 'project-import', 'openMeasureModal'] },
        { id: 'pokladka', label: 'Pokládka / vrstvy', tools: ['vrstvy', 'brutal-gps', 'gps-semafor', 'openCheckDist', 'track-log', 'kompas', 'zavady', 'epochy', 'openMeasureModal'] },
        { id: 'katastr', label: 'Katastr a mapování', tools: ['openKatastr', 'cadastre-vector', 'parcela', 'startAreaMode', 'openTachymetrie', 'project-import', 'openMeasureModal'] },
        { id: 'kontrola', label: 'Kontrola a monitoring', tools: ['openCheckDist', 'epochy', 'zavady', 'openDmtVolume', 'vyska-objektu', 'track-log', 'zapisnik', 'openMeasureModal'] }
    ];

    // ---- JEDEN ZÁZNAM NA NÁSTROJ ------------------------------------------------
    var T = [
        // ── Změřit ──────────────────────────────────────────────────────
        { k: 'openMeasureModal', verb: 'Změřit', vl: 'Vzdálenost a převýšení mezi body', keys: 'vzdalenost delka metry mezi body prevyseni sikma pasmo distance', base: 1,
          help: { t: 'Měření vzdálenosti', h: '<p>Spočítá vodorovnou délku, převýšení a šikmou délku mezi dvěma místy podle GPS.</p><ol><li>Postav se na první místo a klepni <b>Uložit moji aktuální pozici</b> u bodu A.</li><li>Přejdi na druhé místo a ulož bod B.</li><li>Výsledky se dopočítají hned. Přesnost odpovídá GPS telefonu (metry) — pro krátké délky použij pásmo.</li></ol>' } },
        { k: 'ar-metr', verb: 'Změřit', vl: 'Krátkou délku kamerou', vh: 'telefon plocho nad zemí, bez pásma', keys: 'metr pravitko kamera kratka delka bez pasma meritko svinovaci zmerit rukou',
          help: { t: 'Metr v kameře', h: '<p>Pravítko promítnuté do obrazu kamery. Telefon držíš <b>plocho, displejem nahoru</b>, takže zadní kamera kouká kolmo dolů — rovina země je pak rovnoběžná se senzorem, v obraze není perspektiva a měřítko je po celé ploše stejné. Vidíš zhruba <b>1,3 m</b> při výšce držení 1 m a čteš na centimetry.</p><ol><li>Nahoře napiš <b>výšku držení</b> v cm (nebo ťukni předvolbu 80 / 100 / 120). Tohle je jediné, co se v terénu mění.</li><li>Srovnej podle <b>libely</b> vpravo nahoře — dokud není bublina zelená (do 0,7°), hodnoty se červenají.</li><li><b>Stupnice</b> promítne mřížku po 10 cm a kříž s dílky po 1 cm. <b>Délka</b> = klepni na dva body (jde s nimi pak tahat) a přečti mm. <b>Obdélník</b> = dva protilehlé rohy, dostaneš strany i plochu.</li><li><b>Uložit</b> zapíše hodnotu do zakázky; v <b>⋯ → Záznamy</b> je seznam, export CSV a tlačítko <b>K bodu</b> (zapíše se do poznámky bodu, takže je i v záloze a exportech).</li></ol><p><b>Nejdřív jednorázová kalibrace, jinak to lže.</b> Zorný úhel kamery appka u tvého telefonu nezná a bez kalibrace jede na odhadu 66° — může být o desítky procent vedle. Polož na zem svinovák nebo list A4 (dlouhá strana 297 mm), přepni na <b>Délka</b>, klepni na oba konce a v <b>⋯ → Zkalibrovat</b> zadej skutečnou délku. Kalibrace se ukládá <b>zvlášť pro každé rozlišení kamery</b>. Kdo nezná výšku držení, může to obrátit — tlačítkem <b>Doladit výšku držení</b> se dopočítá ona.</p><p><b>Meze, se kterými musíš počítat:</b> chyba zadané výšky se propisuje 1:1 (5 cm z metru = 5 % na všech hodnotách), 1° náklonu dělá ~1 cm na metr u kraje záběru, a u okrajů obrazu zkresluje objektiv — nástroj na to upozorní a měř raději středem. Reálně dosažitelné je <b>±1 %, tedy ±1 cm na metr</b>. Dál než na šířku záběru to nevidí a <b>na šikmo to nejde</b>: chyba by rostla jako h/sin²(úhel pod obzor), na třech metrech už ~15 cm na 1° náklonu. Měří se <b>vodorovný průmět</b> — u nakloněné plochy zadej <b>⋯ → Sklon povrchu</b> a přičte se délka po spádnici. Na přejímku a fakturaci to není, na rychlé „kolik je ta spára“ ano.</p>' } },
        { k: 'startAreaMode', verb: 'Změřit', vl: 'Plochu a obvod pozemku', keys: 'plocha vymera obvod pozemek polygon hektar m2 area', base: 1,
          help: { t: 'Měření plochy', h: '<p>Plocha a obvod polygonu v rovině S-JTSK (Gaussův vzorec) — pro ČR přesný výpočet.</p><ol><li>Klepni do mapy pro přidání vrcholu, nebo obejdi pozemek a přidávej <b>Můj bod</b> (použije průměrovanou GPS).</li><li>Panel dole ukazuje živě plochu, obvod a počet vrcholů.</li><li><b>Vrátit</b> odebere poslední vrchol. <b>Ukončit</b> režim zavře — kdyby ses uklepl, nabídne toast <b>Vrátit zpět</b> a obejitý polygon se obnoví.</li></ol><p>Přesnost je daná GPS: obejitá plocha z mobilu je odhad v jednotkách procent, ne podklad pro výměru do katastru. Přesnou výměru počítej nástrojem Parcela ze zaměřených lomových bodů.</p>' } },
        { k: 'openCheckDist', verb: 'Změřit', vl: 'Oměrné — kontrolní míry', keys: 'omerne kontrolni miry kontrola delek pasmo overeni',
          help: { t: 'Oměrné / kontrola', h: '<p>Kontrola geometrie zaměření: délku, kterou jsi změřil pásmem, porovná s délkou spočítanou ze S-JTSK souřadnic obou bodů. Ukáže, jestli měření drží, nebo jestli je někde chyba.</p><ol><li>Vyber dvojici bodů ze zakázky.</li><li>Zapiš k ní <b>měřenou délku</b> (pásmo, dálkoměr, hodnota z GP nebo náčrtu).</li><li>Odchylka se ukáže v <b>mm i ppm</b>; překročená tolerance se zvýrazní.</li></ol><p>Průměrná odchylka přes všechny dvojice je <b>systematika</b> — když všechny míry táhnou stejným směrem, nejde o náhodnou chybu, ale o měřítko nebo špatné jednotky.</p>' } },
        { k: 'kontrola-vrstvy', verb: 'Změřit', vl: 'Sedí hotová vrstva na projekt?', vh: 'výška za finišerem, odchylka a protokol', keys: 'kontrola vrstvy finiser pokladka asfalt vyska projekt odchylka tloustka protokol',
          help: { t: 'Kontrola vrstvy', h: '<p>Za finišerem: <b>změřeno → projekt → rozdíl</b> velkým číslem a rovnou do protokolu. Navazuje na <b>Vrstvy / pokládka</b>, odkud si bere odsazení mezi vrstvami.</p><ol><li>Opiš <b>Z z roveru</b> (telefon výšku na centimetry neumí — jeho GPS výška je ±1,5 až 4 m).</li><li>Zadej <b>výšku výtyčky</b> nad povrchem — odečte se.</li><li>Zvol projektovou výšku: <b>Pevná kóta</b> (nejpřesnější, nepotřebuje polohu) nebo <b>Rovina z bodů</b> (proloží MNČ body zakázky s výškou, min. 3).</li><li>Velké číslo řekne <b>UBRAT / PŘIDAT</b> a kolik; zelená = v toleranci.</li><li><b>Zapsat do protokolu</b> uloží řádek se souřadnicemi; dole je export do CSV.</li></ol><p>U režimu „Rovina" appka sama spočítá, kolik z nepřesnosti polohy telefonu propadne přes spád do výšky — když je to moc, přepni na pevnou kótu.</p>' } },
        { k: 'openDmtVolume', verb: 'Změřit', vl: 'Kubaturu a vrstevnice', keys: 'kubatura objem vrstevnice dmt teren vykop nasyp hromada',
          help: { t: 'Kubatury / vrstevnice', h: '<p>Digitální model terénu z bodů s výškou: Delaunayho trojúhelníková síť (TIN), z ní <b>vrstevnice</b> a <b>objemy</b> výkopu a násypu vůči srovnávací rovině.</p><ol><li>Vezmou se body zakázky, které mají výšku (Z / Bpv). Data z totálky nebo RTK jde vložit i ručně jako seznam řádků <b>Y X Z</b>.</li><li>Zadej <b>srovnávací výšku</b> — dostaneš objem výkopu, násypu a plochu.</li><li>Krok vrstevnic si nastavíš; model se kreslí do vlastního plátna, hlavní mapy ani AR se nedotkne.</li></ol><p>Přesnost stojí a padá s body: TIN interpoluje jen mezi nimi, mimo obalovou hranu bodů nic nedopočítá a lomové hrany terénu je potřeba zaměřit.</p>' } },
        { k: 'vyska-objektu', cat: 'Měření', verb: 'Změřit', vl: 'Výšku objektu', vh: 'budova, stožár, strom', keys: 'vyska objektu budova strom stozar uhel meridlo',
          help: { t: 'Výška objektu', h: '<p>Trigonometrické určení výšky stožáru, komína, stromu… jen telefonem: zaměříš svislý úhel na patu a na vrchol objektu, výška se dopočítá.</p><ol><li>Zadej výšku telefonu nad zemí (odkud míříš — cca výška očí).</li><li>Vzdálenost k objektu se spočte ze záměru na patu (předpokládá rovnou zem) — nebo ji změř pásmem/krokováním a zadej ručně, bude to přesnější.</li><li>Zamiř kříž na <b>patu</b> objektu a klepni „Zaměřit patu", pak na <b>vrchol</b> a „Zaměřit vrchol".</li></ol><p>Výsledek ukazuje i poctivý odhad ± (typicky decimetry až ~1 m). Zpřesníš ho tím, že jdeš blíž, držíš telefon klidně, nebo zadáš vzdálenost ručně.</p>' } },
        { k: 'korekce', verb: 'Změřit', vl: 'S korekcí na teplotu a tlak', vh: 'pásmo, dálkoměr', keys: 'korekce ppm pasmo teplota tlak vlhkost refrakce zakriveni edm dalkomer atmosfericka oprava pruves',
          help: { t: 'Korekce měření', h: '<p>Tři korekce, které se v terénu počítají pořád — s teplotou, tlakem a vlhkostí předvyplněnými z posledního staženého počasí (a ručně přepsatelnými).</p><ol><li><b>Pásmo:</b> teplotní roztažnost, komparační oprava, průvěs a převod šikmé délky na vodorovnou; rozpis oprav je v mm.</li><li><b>Dálkoměr ppm:</b> atmosférická korekce EDM, kterou zadáš do totálky, včetně toho, kolik to dělá mm na 100 m a na 1 km. Zkontroluj referenční atmosféru svého přístroje v manuálu.</li><li><b>Refrakce:</b> oprava trigonometrického převýšení (1−k)·d²/2R se zadatelným koeficientem.</li></ol><p>Tlak z počasí je na hladině moře, dálkoměr potřebuje tlak v místě — přepočet z výšky GPS je vypsaný nad vstupy. Měřený teploměr a barometr mají vždy přednost před předpovědí; teplota pásma na rozpáleném asfaltu je jiná než teplota vzduchu.</p>' } },
        { k: 'obchuzka', verb: 'Změřit', vl: 'Kubaturu obejitím výkopu', vh: 'obvod z GNSS + dno, objem hned na místě', keys: 'obchuzka vykop kubatura objem obejiti obvod dno jama',
          help: { t: 'Obchůzka výkopu', h: '<p>Kubatura na místě, bez zpracování v kanceláři: obejdeš hranu výkopu, zaměříš dno a hned víš objem — i s poctivým ±.</p><ol><li><b>Obejít hranu</b> zapne automatický záznam (vrchol každých 1,5 m, špatné fixy se zahazují). Na rozích se zastav a dej <b>Roh ručně</b> — pár sekund se průměruje, roh je to nejdůležitější místo obvodu.</li><li><b>Dno:</b> nejlepší je obejít i <b>hranu dna</b> (≥ 3 body) — objem se pak počítá jako <b>komolý jehlan</b> a svahované stěny jsou v tom zahrnuté. Stačí i 1–2 body dna, nebo <b>hloubka ručně</b> (pásmo, lať) — ta je přesnější než výška z GPS.</li><li>Nahoře je objem, plocha (Gaussův vzorec v S-JTSK), obvod a hloubka; vedle objemu ± spočítané z dosažené přesnosti fixů.</li><li><b>Přenést body do zakázky</b> je uloží jako body s kódem „hrana výkopu“ / „dno výkopu“; <b>Do kubatur (TIN)</b> je rovnou předá nástroji Kubatury/vrstevnice. <b>Export CSV</b> vytáhne souřadnice i výsledky.</li></ol><p><b>Svislé stěny jsou horní odhad</b> — bez zaměřeného dna vychází objem větší, než jaký ve skutečnosti je; appka to u výsledku píše. Všechno stojí na GPS mobilu a <b>výška je z ní 2–3× horší než poloha</b>, takže hlavní chybu dělá hloubka: u malého výkopu může být ± v desítkách procent. Na přejímku a fakturaci patří rover nebo totálka. Tenhle nástroj <b>není</b> 3D sken ani fotogrammetrie — model výkopu z videa se v prohlížeči spočítat nedá.</p>' } },

        // ── Určit nový bod ──────────────────────────────────────────────
        { k: 'brutal-gps', cat: 'Měření', verb: 'Určit nový bod', vl: 'Přesnou GPS', vh: 'dlouhé průměrování s otočením', keys: 'presne gps mereni prumer prumerovani brutalni poloha bod', base: 1,
          help: { t: 'Přesná GPS (dlouhé průměrování)', h: '<p>Vysoce přesné měření bodu jen s telefonem: dlouhé průměrování GPS s filtry (pohyb, Wi-Fi poloha, geometrie družic) a robustním odhadem.</p><ol><li>Zkontroluj řádek <b>Skóre místa</b> nahoře — červená = najdi lepší místo nebo čas.</li><li>Polož telefon na bod, zvol plánovanou dobu a spusť. Ve <b>¼, ½ a ¾ času</b> appka vyzve otočit telefon o 90° po směru hodin (vystředí vliv antény a odrazů).</li><li>Výsledek ulož jako bod — u něj zůstane dosažená přesnost. Nebo ho přidej jako <b>sezení</b> a vrať se později (tlačítko „Kdy se vrátit?" poradí čas) — spojený výsledek z více sezení je přesnější.</li></ol><p>Pro maximum přesnosti naplánuj kartou dole <b>kampaň „3 návštěvy"</b>: měření ve třech různých konstelacích družic vyruší velkou část systematické chyby.</p>' } },
        { k: 'rajon', verb: 'Určit nový bod', vl: 'Rajónem', vh: 'směr a délka ze stanoviska', keys: 'rajon polarni metoda uhel delka stanovisko novy bod',
          help: { t: 'Rajón (směr + délka)', h: '<p>Klasická polární metoda: nový bod ze <b>stanoviska</b> (známý bod) pomocí směru a vodorovné délky.</p><ol><li>Vyber stanovisko a orientaci (další známý bod), nebo použij kompas.</li><li>Zadej směr/směrník a délku (pásmo, dálkoměr).</li><li>Bod se spočítá a uloží do zakázky i s poznámkou o původu.</li></ol>' } },
        { k: 'offset-point', cat: 'Vytyčování a náčrt', verb: 'Určit nový bod', vl: 'Offsetem', vh: 'odsazení od jiného bodu', keys: 'odsazeny bod offset kolmice stanoveni vypocet',
          help: { t: 'Offset bod', h: '<p>Bod, ke kterému se nedá dojít nebo na něm nejde stát: roh budovy, střed šachty, pata sloupu, bod za plotem. Spočítá se ze základu + <b>azimutu</b> + <b>vodorovné délky</b>.</p><ol><li>Vyber základ: <b>moje poloha</b> (průměrovaná GPS), nebo některý uložený bod.</li><li>Zadej azimut — buď číslem, nebo ho <b>převezmi z kompasu</b> (namiř telefon na cíl a klepni).</li><li>Zadej vodorovnou vzdálenost (pásmo, dálkoměr) a bod ulož.</li></ol><p>Azimut je <b>zeměpisný</b> (0° = sever, po směru hodin), stejně jako ve zbytku appky. Přesnost je daná přesností základu a kompasu — u budov a kovu je kompas nespolehlivý, pak radši použij Rajón z bodu se známou orientací.</p>' } },
        { k: 'ar-intersection', cat: 'Měření', verb: 'Určit nový bod', vl: 'Protínáním vpřed', vh: 'jen úhly, délku měřit nemůžu', keys: 'protinani vpred uhly neznamy bod urceni',
          help: { t: 'Protínání vpřed', h: '<p>Určení neznámého bodu záměrami ze dvou (i více) známých stanovisek — čistě z úhlů, bez měření délky.</p><ol><li>Postav se na známý bod, zacíl na hledaný bod a ulož záměru.</li><li>Totéž z druhého známého bodu.</li><li>Appka protne směry (více záměr vyrovná MNČ) a bod uloží.</li></ol>' } },
        { k: 'pdr-offset', cat: 'Měření', verb: 'Určit nový bod', vl: 'Krokovým offsetem', vh: 'došlápnutý vektor', keys: 'kroky krokovy offset vektor chuze pdr roh budovy dead reckoning',
          help: { t: 'Krokový offset', h: '<p>Nový bod „došlápnutím": od známého bodu A dojdeš na místo B a appka spočítá B = A + vektor z kroků (akcelerometr) a směru (kompas). Na 10–30 m bývá přesnější než dvě samostatná GPS měření — ideální na rohy budov a místa bez výhledu na oblohu.</p><ol><li>Jednou za čas udělej <b>kalibraci kroku</b>: rovný úsek ≥ 25 m pod volným nebem s dobrým fixem.</li><li>Stoupni si na bod A, vyber ho v seznamu a spusť chůzi.</li><li>Drž telefon volně před sebou displejem nahoru a normálně dojdi na B; zastav a bod pojmenuj + ulož.</li></ol><p>U budov ruší kompas kov — k bodu se proto ukládá poctivý odhad nejistoty (~2 % délky ⊕ chyba směru). Na delší vzdálenosti použij Offset bod s pásmem.</p>' } },
        { k: 'ar-resection', cat: 'AR a kalibrace', verb: 'Určit nový bod', vl: 'Resekcí ze známých bodů', vh: 'určí i sever', keys: 'resekce protinani zpet stanovisko volne zname body',
          help: { t: 'Resekce ze známých bodů', h: '<p>Určení vlastní polohy a severu ze záměr na známé body (obdoba volného stanoviska) — pomáhá tam, kde GPS nestačí.</p><ol><li>Zacíl postupně na 2–3 známé body v terénu.</li><li>Appka dopočítá, kde stojíš, a srovná sever AR.</li></ol>' } },
        { k: 'free-station', verb: 'Určit nový bod', vl: 'Volným stanoviskem', vh: 'průvodce krok za krokem', keys: 'volne stanovisko pruvodce resekce prechodne',
          help: { t: 'Volné stanovisko (průvodce)', h: '<p>Průvodce určením vlastního stanoviska ze záměr na známé body — když nestojíš na žádném známém bodě a GPS nestačí.</p><ol><li>Vyber 2–3 známé body, které z místa vidíš.</li><li>Průvodce tě provede záměrami (deleguje na AR resekci).</li><li>Výsledkem je tvá poloha + srovnaný sever AR.</li></ol>' } },
        { k: 'dgps', cat: 'Měření', verb: 'Určit nový bod', vl: 'Dvoutelefonní DGPS', vh: 'základna a rover', keys: 'dgps diferencni korekce zakladna rover druhy telefon presnost oprava bodu',
          help: { t: 'Dvoutelefonní DGPS', h: '<p>Korekce z druhého mobilu: atmosférická chyba GPS je do ~2 km pro oba telefony stejná. Základna na známém bodě ji průběžně měří a body roveru se o ni zpětně opraví — typicky na polovinu až třetinu chyby. Funguje offline.</p><ol><li><b>Základna:</b> druhý telefon polož na bod se spolehlivě známými souřadnicemi (import S-JTSK, ne bod měřený mobilem), spusť a nech ležet po CELOU dobu měření.</li><li><b>Rover:</b> tímto telefonem normálně měř body (Brutální GPS / průměrovaná GPS).</li><li>Na základně klepni <b>Zastavit a ukázat QR s korekcemi</b>.</li><li>Zde otevři režim <b>Korekce</b>, klepni <b>Naskenovat QR ze základny</b> a namiř kameru na displej druhého telefonu (nebo použij přenos souborem). Zkontroluj nabídnuté posuny a potvrď.</li></ol><p>Opraví se jen body měřené v době běhu základny a do 3 km od ní; posun se zapíše do žurnálu bodu a aplikuje se nejvýš jednou.</p>' } },
        { k: 'hlas-kod', verb: 'Určit nový bod', vl: 'Hlasem — nadiktovat číslo a kód', vh: 'bez ťukání v rukavicích', keys: 'hlas hlasem kod bod diktovat rukavice mluvit cislo poznamka',
          help: { t: 'Hlasové kódování bodu', h: '<p>Místo ťukání do klávesnice v rukavicích řekneš jednu větu: <b>„Bod 105, roh plotu, poznámka zborcený sloupek.“</b> Appka ji rozebere na číslo, kód a poznámku, ukáže to velkým písmem a po povelu <b>„ulož“</b> založí bod z průměrované GPS.</p><ol><li>Klepni <b>Začít poslouchat</b> a mluv; rozebraná věta je hned vidět ke kontrole.</li><li>Doplňovat jde po částech: <b>„kód obruba“</b>, <b>„výška 312,45“</b> (výška ručně místo GPS).</li><li><b>„ulož“</b> spustí průměrování (výchozí 5 s) a bod uloží · <b>„zruš“</b> vymaže rozepsané · <b>„další“</b> posune na další číslo série · <b>„konec“</b> vypne poslech.</li><li>Po uložení ti appka odpoví hlasem („uloženo 105“), ať se nemusíš dívat na displej. Vypínatelné.</li></ol><p><b>Nic se neuloží bez povelu</b> — hlas kolegy nesmí založit bod. <b>Potřebuje signál</b>: prohlížeč posílá zvuk na server výrobce, a na iPhonu Web Speech často chybí úplně; okno to napíše a nabídne <b>Hlasové poznámky</b> (nahrají zvuk a přepíšou ho později). Slovník je schválně malý — co appka nepozná, neudělá. Číslování se sdílí s ručním „Nový bod“, takže v sérii nevznikají díry.</p>' } },

        // ── Vytyčit ─────────────────────────────────────────────────────
        { k: 'openStakeoutModal', verb: 'Vytyčit', vl: 'Body podle seznamu', vh: 'vytyčovací checklist', keys: 'vytyceni vytycovaci checklist seznam protokol', base: 1,
          help: { t: 'Vytyčovací checklist', h: '<p>Odškrtávání vytyčených bodů: dojdu k bodu, zatluču kolík, odkliknu hotovo. Přehled, co ještě zbývá, i po zavření appky — stav se drží per zakázka.</p><ol><li>V seznamu klepni na bod — appka ho <b>zvýrazní a naviguje</b> na něj (šipka v AR).</li><li>Po zatlučení bod <b>odškrtni</b>; uloží se čas a přesnost GPS v okamžiku odškrtnutí.</li><li>Přepínačem <b>Jen vlastní body</b> schováš úřední body, ať v seznamu nepřekáží.</li><li><b>Export protokolu vytyčení (CSV)</b> vytáhne seznam i s časy pro kancelář.</li></ol><p>Odškrtnutí je vázané na bod, ne na jeho polohu — když bod smažeš a založíš znovu, začíná neodškrtnutý.</p>' } },
        { k: 'stakeout-line', cat: 'Vytyčování a náčrt', verb: 'Vytyčit', vl: 'Přímku', keys: 'vytyceni primky linie rovina stanoveni smeru',
          help: { t: 'Vytyčení přímky', h: '<p>Pro liniové stavby (plot, obruba, výkop, lavičky): zadáš přímku dvěma body A→B a appka ti za chůze ukazuje, kde na ní jsi.</p><ol><li>Vyber počáteční bod A a koncový bod B ze zakázky.</li><li>Za chůze čteš <b>staničení</b> (jak daleko jsi od A po ose), <b>kolmý odstup</b> (o kolik jsi vlevo či vpravo) a <b>zbývá do B</b>.</li><li>Obráceně umí i <b>vytyčit bod</b> na zadaném staničení (volitelně s kolmým posunem) a uložit ho jako bod zakázky.</li></ol><p>Počítá se v rovině kolem A — na délky přímky v kilometrech to sedí. Kolmý odstup je jen tak přesný jako tvoje GPS, takže na centimetrové práce použij pásmo od vytyčených bodů.</p>' } },
        { k: 'vrstvy', cat: 'Vytyčování a náčrt', verb: 'Vytyčit', vl: 'Vrstvu pokládky', vh: 'výška a sklon za finišerem', keys: 'vrstvy pokladka skladba silnice asfalt sklon rez finisher tablet',
          help: { t: 'Vrstvy / pokládka', h: '<p>Skladby vozovky per stavba/úsek: vrstvy shora dolů s tloušťkou a % nadvýšení na hutnění. Vrstvy přidáš <b>z katalogu</b> (ACO, ACL, ACP, SMA, MZK, ŠD…) nebo vlastní; zkratky vysvětluje slovníček dole.</p><ol><li>Vyber, které vrstvě odpovídá <b>model v kontroleru</b> (horní plocha).</li><li>Vyber, kterou vrstvu <b>pokládáš</b>.</li><li>Nahoře svítí hodnota <b>Do tabletu</b> = odsazení mezi vrstvami + nadvýšení na hutnění.</li></ol><p>V <b>řezu</b> tažením čáry mezi vrstvami měníš tloušťku; sklon (jednostranný i střechovitý) je jen náhled, převýšený. Výchozí % hutnění jsou orientační — uprav dle zhutňovací zkoušky.</p>' } },
        { k: 'indoor', verb: 'Vytyčit', vl: 'Dojít k bodu uvnitř budovy', vh: 'bez GPS; navádí, nevytyčuje', keys: 'uvnitr budovy bez gps interier hala navadeni krokovani',
          help: { t: 'Uvnitř budovy', h: '<p>V hale, garážích nebo tunelu končí GPS. Tenhle nástroj drží polohu dál: od bodu, který znáš, počítá posun a ukazuje vzdálenost i směr k bodům zakázky — do vlastního půdorysu, protože mapa by uvnitř ukazovala střechu.</p><ol><li>Vyber, <b>odkud vycházíš</b> — bod, na kterém stojíš (nejlepší), nebo poslední GPS u vchodu.</li><li><b>Začít sledovat polohu</b>. Na Androidu se zkusí <b>vizuální sledování (WebXR)</b> z kamery a čidel; kde není (iPhone), počítají se <b>kroky</b> z akcelerometru a směr z kompasu.</li><li>Nahoře pořád svítí <b>nejistota</b> a v půdorysu je jako kruh. Roste s ušlou dráhou.</li><li>Jakmile dojdeš k zaměřenému bodu, vyber ho a klepni <b>Jsem na bodě</b> — poloha se srovná, nejistota spadne na nulu a appka ti ukáže, <b>jaký drift</b> se do té chvíle nasbíral. To číslo říká, jak často se musíš vázat.</li></ol><p><b>Tohle není vytyčování.</b> Nejistota nespadne pod decimetry a po padesáti metrech chůze jsou to metry — příčky, prostupy a otvory patří totálce nebo laseru. Uvnitř budov navíc <b>střílí kompas</b> (kov, rozvaděče, výtahy), takže krokový výpočet driftuje víc než venku. Délka kroku se kalibruje venku v nástroji <b>Krokový offset</b> (sdílená hodnota). IFC/BIM appka nečte — půdorys si natáhni jako DXF nástrojem <b>Import projektu</b> a lomové body přenes do zakázky.</p>' } },

        // ── Zaznamenat ──────────────────────────────────────────────────
        { k: 'openTachymetrie', verb: 'Zaznamenat', vl: 'Náčrt / tachymetrii', keys: 'nacrt kresba skica tachymetrie zpmz polni nakres',
          help: { t: 'Náčrt / Tachymetrie', h: '<p>Digitální náhrada ručního polního náčrtu: body se kreslí na správné poloze nad zvoleným podkladem (mapa, ortofoto, nebo bez podkladu), spojují se čarami různých typů a jdou doplnit popisky.</p><ol><li>Přidávej body ze své polohy, nebo tlačítkem <b>Mé body</b> natáhni body ze zakázky.</li><li>Spojuj je čarami, vkládej texty (např. „kámen" uvnitř plochy); u čar se dopočítávají délky a u uzavřených obrazců plocha.</li><li><b>Export do PNG</b> se zeptá, jestli chceš <b>čistý náčrt na bílém</b> (do elaborátu), nebo <b>náčrt i s podkladní mapou</b> (na doložení, kde to je).</li></ol><p><b>Náčrtů může být víc.</b> Vlevo v liště je rozbalovátko s náčrty a vedle něj <b>+</b> (nový), <b>tužka</b> (přejmenovat) a <b>koš</b> (smazat tenhle náčrt i s obsahem). Přepnutím se rozdělaná práce nikam neztratí — každý náčrt se ukládá zvlášť v telefonu.</p>' } },
        { k: 'zapisnik', cat: 'Měření', verb: 'Zaznamenat', vl: 'Zápisník', vh: 'nivelace, směry', keys: 'zapisnik polni denik poznamky mereni zaznamy', base: 1,
          help: { t: 'Zápisníky', h: '<p>Digitální zápisník místo papíru: <b>technická nivelace</b> (čtení zpět/vpřed → převýšení, výšky, uzávěr) a <b>vodorovné směry</b> — pro každý cíl skupiny s Hz v I./II. poloze (redukce + průměry), zenitové úhly v obou polohách (zprůměruje se) a šikmá či vodorovná délka (šikmá se zenitem se přepočte na vodorovnou a převýšení).</p><p>Výpočty běží průběžně (lze vypnout v hlavičce zápisníku). Data se ukládají per zakázka a jdou exportovat.</p>' } },
        { k: 'zavady', verb: 'Zaznamenat', vl: 'Závadu s fotkou', keys: 'zavada zavady porucha vada nalez hlaseni defekt kontrola oprava foto protokol reklamace',
          help: { t: 'Závady / hlášení', h: '<p>Zápis nálezu v terénu na pár ťuknutí: foto → kategorie → závažnost → poznámka. Poloha, čas a přesnost GPS se doplní samy. Závadu můžeš <b>vázat na konkrétní měřený bod</b> („jaký bod a co je s ním špatně") — poloha se pak převezme z bodu a jeho jméno je v seznamu, CSV i protokolu.</p><ol><li>Otevři nástroj (nebo <b>podrž tlačítko „Nový bod"</b> v doku) a vyplň formulář.</li><li>Závady svítí jako barevné vykřičníky v mapě i AR — podle závažnosti.</li><li>V seznamu je odškrtávej jako <b>Vyřešeno</b>; nic se neztratí.</li></ol><p>Export: CSV se S-JTSK souřadnicemi a tiskový protokol s fotkami (uložíš jako PDF).</p>' } },
        { k: 'hlasovky', verb: 'Zaznamenat', vl: 'Hlasovou poznámku', vh: 's georazítkem', keys: 'hlasovka nahravka diktafon zvuk mluvena poznamka audio',
          help: { t: 'Hlasové poznámky', h: '<p>Nadiktované poznámky, které se rovnou <b>přepíšou na text</b> — v rukavicích a blátě se nepíše a samotný zvuk by se v kanceláři musel přehrávat. Každá poznámka dostane <b>georazítko</b>: čas, polohu (S-JTSK), přesnost GPS a nejbližší vlastní bod do 25 m („u bodu 105, 3 m").</p><ol><li>Klepni <b>Nahrát poznámku</b> a mluv — text naskakuje živě pod tlačítkem. Dalším klepnutím zastavíš (strop 5 minut).</li><li>Přepis si v seznamu <b>zkontroluj a oprav</b> — rozpoznávání komolí hlavně jména a žargon (S-JTSK, Bpv, ZPMZ appka opraví sama). Zvuk zůstává uložený jako důkaz.</li><li>Chybí-li přepis, klepni <b>Diktovat</b> a nadiktuj text dodatečně, nebo ho napiš.</li><li>Když je poznámek víc, hledej v nich políčkem nahoře. Večer je posbírá <b>Deník dne</b> i s textem.</li></ol><p><b>Přepis nemusí být k dispozici</b>: na iPhonu (a v PWA) ho prohlížeč často vůbec neumí — okno to hned pod tlačítkem napíše a poznámka se uloží <b>jako zvuk</b>, nahrávání běží dál. <b>Přepis taky potřebuje signál</b> (prohlížeč posílá zvuk na server výrobce) — offline se uloží jen zvuk a text dopíšeš později. Přepis jde vypnout přepínačem v hlavičce; na iOS to zkus, kdyby mikrofon škubal obrazem kamery v AR. Data zůstávají jen v telefonu (necloudují se, nejdou v exportu zakázky).</p>' } },
        { k: 'denik-dne', verb: 'Zaznamenat', vl: 'Deník dne', keys: 'denik dne zaznam prace vykaz co jsem delal poznamky',
          help: { t: 'Deník dne', h: '<p>Večerní souhrn dne za aktivní zakázku na jeden tap — podklad pro kancelář nebo stavební deník: nové/změněné/smazané body, docházka party, závady včetně stavu, počasí, ušlá stopa a založené zápisníky.</p><ol><li>Otevři dlaždici — souhrn za <b>dnešek</b> se sestaví sám; nahoře přepneš na včerejšek nebo libovolné datum.</li><li><b>Sdílet</b> pošle čistý textový report (mail, WhatsApp…); kde sdílení není, zkopíruje se do schránky.</li><li><b>Uložit PDF</b> otevře tiskový protokol — ulož přes systémový tisk (povol vyskakovací okna).</li></ol><p>Čte jen data z tohoto zařízení: docházka píchnutá na jiném telefonu tu není a staré body bez časového razítka nejde zařadit ke dni. Funguje offline (počasí ukáže poslední stažená data ze zvoleného dne).</p>' } },
        { k: 'track-log', cat: 'Měření', verb: 'Zaznamenat', vl: 'Stopu trasy', keys: 'stopa trasa log gpx zaznam cesty prochazka',
          help: { t: 'Stopa trasy', h: '<p>Záznam prošlé trasy (GPS stopa) do mapy: obchůzka hranice, zaměření cesty. Stopu jde uložit a exportovat (GPX/KML).</p><ol><li>Klepni <b>Spustit nahrávání</b> — stopa se kreslí oranžově do mapy, bod se bere po posunu ≥ 1,5 m (šetří GPS šum i baterii).</li><li>Zaškrtnutím <b>Zobrazit stopu i v AR</b> uvidíš čáru položenou po zemi i v kameře — praktické, když se vracíš po vlastní stopě.</li><li><b>Export GPX</b> uloží trasu pro Kokeš, QGIS nebo mapy.</li></ol>' } },
        { k: 'geo-foto', verb: 'Zaznamenat', vl: 'Fotku s razítkem', vh: 'S-JTSK, výška, čas a azimut ve fotce', keys: 'fotka foto razitko georazitko snimek dokumentace souradnice',
          help: { t: 'Geo-fotka', h: '<p>Fotka, u které je i po přeposlání mailem nebo přes WhatsApp pořád vidět, <b>kde a kdy</b> vznikla: razítko se <b>vypálí přímo do pixelů</b> — zakázka, S-JTSK, výška Bpv, datum a čas, azimut pohledu a přesnost GPS. EXIF se při přeposílání zahazuje, vypálené razítko ne.</p><ol><li>Klepni <b>Vyfotit s razítkem</b> — otevře se hledáček a nahoře vidíš živě, co se do fotky vypálí (když chybí azimut nebo fix, je to napsané <b>dřív</b>, než zmáčkneš spoušť).</li><li>Do řádku dole můžeš přidat krátkou poznámku, která bude v razítku.</li><li>Fotka do 25 m od tvého bodu se k němu sama přiváže; tlačítkem <b>K bodu</b> ji připojíš na kartu bodu.</li><li><b>Uložit PDF</b> udělá protokol za den nebo celou zakázku — fotky, souřadnice, otisky.</li></ol><p><b>Co razítko nedokazuje:</b> vypálené pixely jde v editoru přemalovat. Proto se u každé fotky počítá otisk <b>SHA-256</b> a ukládá se s otiskem té předchozí — tlačítko <b>Ověřit řetěz</b> offline zkontroluje, že sada nebyla po pořízení zaměněná ani přeházená. Není to elektronický podpis podle eIDAS. Když kamera nejde (odmítnuté povolení), fotí se systémovou aplikací a <b>azimut se neuloží</b> — vymyšlený směr by byl horší než přiznané „neurčen“. Fotky jsou jen v tomhle telefonu.</p>' } },
        { k: 'epochy', cat: 'Měření', verb: 'Zaznamenat', vl: 'Epochy — posuny v čase', vh: 'opakované měření bodu', keys: 'epochy monitoring posuny deformace sledovani opakovane',
          help: { t: 'Epochy / monitoring', h: '<p>Sledování, jestli se bod v čase <b>hýbe</b> (monitoring posunů): římsa mostu, opěrná zeď, sesuv, skládka… Stejný bod opakovaně zaměříš <b>totálkou nebo GNSS roverem</b> a výsledné souřadnice sem po každém měření zapíšeš jako novou „epochu".</p><ol><li>Založ sledovaný bod — nový, nebo vyber existující z vlastních bodů.</li><li>Po každém měření přidej epochu: souřadnice Y/X/Z zapiš ručně, vyfoť displej či protokol (přečte je OCR), nebo je převezmi z bodu v appce.</li><li>První epocha je <b>referenční</b> — polohový posun ΔP a výškový ΔZ všech dalších epoch se počítají proti ní.</li></ol><p>Volitelně nastav mezní odchylky v mm — při překročení se bod označí červeně. Vývoj posunů ukazuje graf, vše jde exportovat do CSV. GPS mobilu je jen nouzová možnost (přesnost ±metry, pro skutečný monitoring nestačí).</p><p>V detailu sledovaného bodu jde nastavit <b>připomínku přeměření</b> (každých 7/14/30 dní nebo vlastní interval). Appka po startu upozorní lištou na body po termínu (počítá se od poslední epochy) a na dlaždici nástroje svítí červená tečka s počtem; volitelně jdou zapnout i systémové notifikace.</p>' } },
        { k: 'kvalita-bodu', verb: 'Zaznamenat', vl: 'Protokol kvality', vh: 'čím byl bod změřen a jak dobře', keys: 'kvalita protokol presnost sigma smerodatna odchylka epochy doklad rozptyl mereni doložit',
          help: { t: 'Protokol kvality', h: '<p>Tabulka všech bodů zakázky s tím, <b>čím byly změřeny a jak dobře</b>. Appka rozptyl počítala už dřív, ale k bodu se z toho dostalo jen jedno číslo — tady je celý doklad: „bod je z 240 odečtů, rozptyl σ 0,42 m“ je doložitelné, „±0,3 m“ je jen tvrzení.</p><ol><li>Otevři dlaždici — body jsou seřazené od nejnovějšího.</li><li>Sloupec <b>± chyba</b> je směrodatná chyba výsledné polohy, <b>σ</b> rozptyl jednotlivých odečtů kolem středu, <b>epoch</b> kolik odečtů se použilo (a kolik jich celkem přišlo).</li><li><b>Protokol (.txt)</b> uloží čitelný soupis k zakázce, <b>Tabulka (.csv)</b> otevře v Excelu.</li></ol><p>Rozptyl mají jen body, které vznikly z GPS — u ručně zadaných Y/X je pomlčka, protože žádné odečty nemají a číslo by lhalo. Nejvíc údajů nesou body z <b>Přesné GPS (dlouhé průměrování)</b>; ta zapisuje i počet epoch přes všechna sezení re-okupace.</p><p><b>Co to neříká:</b> hodnoty popisují jen <b>vnitřní shodu</b> měření telefonem. Systematickou chybu (odrazy signálu od fasád, troposféra) průměrování neodstraní — proto se ± chyba zdola omezuje reálnou mezí. Kontrolní měření nezávislou metodou to nenahrazuje.</p>' } },
        { k: 'kos', verb: 'Zaznamenat', vl: 'Obnovit smazaný bod', vh: 'koš — body i zakázky, 30 dní', keys: 'kos smazane body obnovit odpadky obnova vratit zpet zakazky',
          help: { t: 'Koš — obnovení smazaného', h: '<p>Smazané zakázky a vlastní body se nezahazují hned: <b>30 dní</b> leží v koši a dají se vrátit. Toast „Vrátit zpět“ zmizí za pár vteřin, tohle zůstává — omylem smazaná zakázka z terénu tedy není definitivní ztráta.</p><ol><li>Otevři koš a najdi položku podle času smazání.</li><li><b>Obnovit</b> ji vrátí zpátky i se spojnicemi a nastavením.</li></ol><p>Vejde se <b>15</b> posledních záznamů a po 30 dnech se zahodí samy. Stažené úřední body se do koše neukládají — jsou velké a jdou kdykoli stáhnout znovu z ČÚZK. Koš žije jen v tomhle telefonu, takže nenahrazuje zálohu.</p>' } },

        // ── Srovnat AR ──────────────────────────────────────────────────
        { k: 'usadit-ar', verb: 'Srovnat AR', vl: 'Nevím čím začít — průvodce', vh: 'značky nesedí na realitu', keys: 'usadit srovnat kalibrace sever ar pruvodce orientace nesedi posun helmert resekce stanovisko',
          help: { t: 'Usadit AR (průvodce)', h: '<p>Jeden vstup místo sedmi kalibračních nástrojů: průvodce se zeptá, co tě trápí (pootočené značky / posun / nevím kde stojím / usadit zakázku) a sám spustí správný nástroj.</p><p>Skryté kalibrační dlaždice najdeš dál přes vyhledávání; vrátit je můžeš v Nastavení → Vzhled → „Zjednodušené Nástroje".</p>' } },
        { k: 'kompas', verb: 'Srovnat AR', vl: 'Podívat se na kompas', vh: 'růžice se zeměpisným i magnetickým severem', keys: 'kompas busola ruzice sever magneticky zemepisny pravy azimut deklinace smer strelka gon nula', base: 1,
          help: { t: 'Kompas a sever', h: '<p>Klasická růžice s <b>oběma severy</b> naráz: bílá špice je <b>zeměpisný</b> (pravý) sever, se kterým appka počítá všechny azimuty, červená střelka je <b>magnetický</b> sever, který ukazuje busola v ruce. Zelená ryska nahoře je pevná — pod ní se čte, kam právě míří telefon.</p><ol><li>Drž telefon <b>naplocho</b> a dál od kovu (auto, plot, výztuž, rozvaděč) — magnetometr je nejslabší článek AR a u kovu se umí splést o desítky stupňů.</li><li>Vedle růžice jsou oba azimuty vypsané číslem a pod nimi <b>deklinace</b> v tvém místě (počítá se z polohy, kladná = na východ).</li><li>Když kompas zlobí, projdi „<b>Jak zkalibrovat kompas</b>" (osmička telefonem) nebo si ho ověř tlačítkem <b>podle Slunce</b>.</li><li>Ve stejném okně je i <b>uživatelská nula</b> (přenastaví jen zobrazené číslo) a <b>Srovnání severu</b> (posune AR i mapu) a přepínač <b>stupně / grady</b>.</li></ol><p>Neplet si obojí v jednom výpočtu: v Česku je deklinace kolem 5° na východ, což je na 100 m posun skoro 9 m. Azimuty z appky, z katastru i ze souřadnic jsou <b>zeměpisné</b>; magnetický údaj je tu na srovnání s busolou a na starší náčrty. Na počítači bez senzoru zůstane růžice na „čekám…".</p>' } },
        { k: 'agOpenCalibrate', verb: 'Srovnat AR', vl: 'Srovnat sever', keys: 'sever kalibrace kompas azimut srovnat smer odchylka', base: 1,
          help: { t: 'Srovnat sever', h: '<p>Kalibrace severu AR podle známého bodu: zacílíš na bod v terénu a appka dorovná otočení kompasu tak, aby AR sedělo.</p><ol><li>Vyber v mapě/AR bod, který v terénu bezpečně vidíš.</li><li>Namiř na něj střed obrazovky a potvrď.</li><li>Korekce severu se uloží (zrušíš ji v Kompasu).</li></ol>' } },
        { k: 'ar-calib2', verb: 'Srovnat AR', vl: 'Srovnat na dva body', keys: 'srovnat ar dva body kalibrace posun sever usadit znacky nesedi',
          help: { t: 'Srovnat AR na 2 body', h: '<p>Přesnější kalibrace AR podle <b>dvou</b> známých bodů: appka srovná natočení (sever) i posun tak, aby oba body v AR seděly na skutečnost.</p><ol><li>Vyber první bod, který v terénu bezpečně vidíš, zamiř na něj střed obrazovky a potvrď.</li><li>Totéž s druhým bodem — ideálně v jiném směru (ne v zákrytu).</li><li>Korekce se uloží; zrušíš ji novou kalibrací nebo v Kompasu.</li></ol><p>Oproti „Srovnat sever" (1 bod) řeší i posun polohy — hodí se, když GPS „táhne" stranou.</p>' } },
        { k: 'orient-point', cat: 'AR a kalibrace', verb: 'Srovnat AR', vl: 'Srovnat sever podle bodu', vh: 'opravuje AZIMUT, ne polohu', keys: 'orientace bod sever srovnani smer',
          help: { t: 'Srovnat sever podle bodu', h: '<p>Rychlé dorovnání severu AR podle bodu, který v terénu vidíš — magnetický kompas je nejslabší článek AR a u aut, plotů a vedení se umí splést o desítky stupňů.</p><ol><li>Vyber známý bod, na který je odsud vidět (trigonometrický, bodové pole, dříve zaměřený roh).</li><li>Namiř na něj střed obrazovky a potvrď.</li><li>Appka porovná skutečný azimut k bodu s tím, co hlásí kompas, a rozdíl uloží jako korekci severu.</li></ol><p>Korekce je stejná páka jako „Srovnání severu" v Kompasu — tam ji taky vynuluješ. Čím dál cílový bod je, tím přesnější srovnání. Jednodušší varianta „Srovnat sever"; posun polohy řeší až „Srovnat AR na 2 body".</p>' } },
        { k: 'localization-helmert', verb: 'Srovnat AR', vl: 'Lokalizace (Helmert)', vh: 'místní systém', keys: 'helmert lokalizace transformace klic mistni system',
          help: { t: 'Lokalizace (Helmert)', h: '<p>Usazení měření na známé body Helmertovou transformací: z dvojic <b>identických bodů</b> (moje měření ↔ dané souřadnice) spočítá posun, natočení a měřítko a aplikuje je na zakázku.</p><ol><li>Přiřaď aspoň 2 identické body (víc = kontrola, vyrovnání MNČ).</li><li>Zkontroluj odchylky na jednotlivých bodech (rezidua).</li><li>Potvrď — transformace se aplikuje; jde vrátit.</li></ol>' } },
        { k: 'ref-calibration', verb: 'Srovnat AR', vl: 'Opravit posun GPS podle bodu', vh: 'opravuje POLOHU, ne sever', keys: 'kalibrace referencni bod srovnani ar posun usazeni znamy bod',
          help: { t: 'Posun GPS na známý bod', h: '<p>Oprava systematického posunu GPS podle známého bodu. Postavíš se na bod se spolehlivými souřadnicemi, appka porovná, kam ho hlásí GPS, a rozdíl si zapamatuje jako konstantní posun.</p><ol><li>Stoupni si na známý bod a nech ustálit GPS (čím delší průměrování, tím lépe).</li><li>Zadej jeho souřadnice — S-JTSK Y/X, WGS84, nebo ho vyber z uložených bodů.</li><li>Potvrď posun. Od té chvíle se přičítá k <b>nově ukládaným</b> bodům, dokud korekci nevypneš.</li></ol><p>Pozor na dvě věci: posun se aplikuje na nově zakládané body, <b>ne</b> na zobrazovanou polohu a <b>ne</b> zpětně na už uložené body (ty zůstanou beze změny). A platí jen na malém území (stovky metrů) a krátkou dobu — jde o lokální korekci, ne RTK. Jinou cestou je Dvoutelefonní DGPS.</p>' } },
        { k: 'fov-kalib', verb: 'Srovnat AR', vl: 'Změřit zorný úhel kamery', keys: 'zorny uhel kamery fov kalibrace ohnisko sirka zaberu ar presnost',
          help: { t: 'Zorný úhel kamery (FOV)', h: '<p>Změří skutečný zorný úhel kamery tvého telefonu. AR podle něj počítá, kam na obrazovku značku nakreslit — když je zadaný špatně, body <b>uprostřed</b> obrazu sedí, ale ke <b>krajům</b> se rozjíždějí. Každý model telefonu má jiný, hádat ho posuvníkem je loterie.</p><ol><li>Běž ven, zkalibruj kompas (osmička telefonem) a vyber si <b>vzdálený</b> osamocený objekt — stožár, komín, roh domu. Musí být dál než ~50 m, jinak se do měření promítne i to, jak se přitom pohneš.</li><li>Otoč telefon tak, aby objekt ležel přesně u <b>levé</b> hrany obrazu, a klepni Zaznamenat. Pak tak, aby byl u <b>pravé</b> hrany, a zaznamenej znovu — rozdíl azimutů je vodorovný zorný úhel.</li><li>Zopakuje se to 3× a bere se prostřední hodnota; kompas kolísá, takže jedno měření nestačí. Rozptyl nad 6° znamená „změř to znovu".</li><li>Svislý úhel buď změříš stejně (vysoký objekt u horní a dolní hrany, sleduje se sklon telefonu), nebo si ho nech dopočítat z poměru stran obrazu.</li><li>Nakonec <b>Uložit do nastavení</b>.</li></ol><p>Když kompas zlobí, je uvnitř popsaná i metoda přes zeď: ve známé vzdálenosti D změříš šířku W mezi kraji obrazu a platí FOV = 2·arctg(W/2D). Kontrola po uložení: bod, který v terénu vidíš, musí v AR sedět i u kraje obrazovky, ne jen uprostřed.</p>' } },
        { k: 'ar-visual-track', verb: 'Srovnat AR', vl: 'Vizuální stabilizace', vh: 'beta', keys: 'stabilizace ar obraz kamera drift plavani znacek vizualni beta',
          help: { t: 'Vizuální stabilizace AR (beta)', h: '<p>Ukotví AR obraz pomocí kamery (optický tok): značky se méně třesou a neplavou při pohybu telefonu.</p><p>Zapíná se zde nebo v Nastavení → AR &amp; přesnost. Stojí něco baterie navíc — vypni, když ji potřebuješ šetřit. Beta: kdyby AR „ujíždělo", vypni a nahlas kdy se to stalo.</p>' } },

        // ── Zjistit podmínky ────────────────────────────────────────────
        { k: 'gps-semafor', cat: 'Měření', verb: 'Zjistit podmínky', vl: 'Dá se tady měřit?', vh: 'skóre místa, odrazy od fasád', keys: 'semafor skore mista multipath signal kvalita gps fasada odrazy podminky',
          help: { t: 'Skóre místa (GPS)', h: '<p>Semafor 🟢/🟠/🔴 <b>před</b> měřením: spojí geometrii družic (PDOP), tvoji elevační masku z Predikce signálu, přesnost hlášenou telefonem a okolí.</p><ol><li>Vyber, co máš kolem sebe: <b>volné nebe</b> / <b>stromy či jedna zeď</b> / <b>mezi budovami</b>.</li><li>Přečti verdikt a tipy — např. „posuň se od zdi" nebo za kolik minut bude lepší konstelace (hledá do 2 h dopředu).</li></ol><p>Odrazy od fasád a aut (multipath) dělají chyby v metrech, které průměrování NEodstraní — prevence je účinnější než dlouhé měření. Skóre vidíš i přímo v Brutální GPS.</p>' } },
        { k: 'openSatModal', verb: 'Zjistit podmínky', vl: 'Družice teď', vh: 'kolik jich vidím a jaká geometrie', keys: 'gnss satelity druzice obloha prekazky signal gps kvalita',
          help: { t: 'GNSS satelity', h: '<p>Přehled družic (GPS, Galileo, GLONASS, BeiDou) nad obzorem: kolik jich je, kde na obloze a jaká je geometrie.</p><p>Málo družic nízko nad obzorem = horší přesnost. Použij před přesnějším měřením — počkej si na lepší konstelaci.</p>' } },
        { k: 'sky-obstruction', verb: 'Zjistit podmínky', vl: 'Predikci signálu', vh: 'maska překážek', keys: 'predikce signalu obloha prekazky stromy budovy gnss planovani',
          help: { t: 'Predikce signálu', h: '<p>Skyplot pro aktuální polohu a čas: posuvníkem nastavíš elevační masku (kolik oblohy zaclání domy, stromy, svah) a appka ukáže, kolik družic zbude nad maskou a jak dobrá bude geometrie (PDOP).</p><p>Hodí se pro plánování měření v zástavbě nebo u lesa.</p>' } },
        { k: 'gnss-forecast', verb: 'Zjistit podmínky', vl: 'Kdy bude nejlíp měřit', vh: 'GNSS předpověď', keys: 'gnss predpoved kdy merit pdop dop okno planovani ionosfera kp bourka geometrie druzic pocasi pro gps', net: 1,
          help: { t: 'GNSS předpověď', h: '<p>Předpověď podmínek pro měření GPS na 24 hodin dopředu — jako předpověď počasí, ale pro družice. Řekne ti, kdy dnes dělat nejpřesnější body a kdy měření odložit.</p><ol><li>Otevři dlaždici; appka spočítá po hodinách <b>PDOP</b> (geometrii družic) z jejich drah a přidá <b>Kp index</b> (stav ionosféry z NOAA).</li><li>Zelený puntík = výborné podmínky, žlutý = použitelné, červený = slabá geometrie nebo geomagnetická bouře.</li><li>Nahoře je <b>nejlepší okno</b> — na něj si naplánuj vytyčení, kontrolu nebo Brutální GPS.</li></ol><p>Dráhy družic (TLE) a Kp se stahují z internetu, pak fungují dny offline z cache. Předpověď platí pro <b>otevřený obzor</b> — stínění stromy a domy posoudí nástroj „Predikce signálu". Bouřková poznámka je bezpečnostní, s přesností GNSS nesouvisí.</p>' } },
        { k: 'pocasi', verb: 'Zjistit podmínky', vl: 'Počasí', keys: 'pocasi predpoved dest vitr teplota radar srazky obloha bourka', net: 1,
          help: { t: 'Počasí', h: '<p>Předpověď pro místo měření složená až z <b>33 zdrojů</b> — 19 předpovědních modelů (ECMWF vč. AI modelů AIFS/GraphCast, DWD ICON, <b>ČHMÚ ALADIN v rozlišení 1 km</b>, KNMI a DMI HARMONIE, GeoSphere AROME, Météo-France, UK Met Office, NOAA, JMA, CMA, BOM, CMC), MET Norway, DWD MOSMIX, <b>11 ensemblů</b> (vč. Google WeatherNext 2 se 64 běhy) a v Česku navíc naměřená data <b>ČHMÚ</b>. Všechny hodnoty se váženě průměrují — dlaždice <b>Shoda zdrojů</b> ukazuje, jak moc se modely rozcházejí; velký rozptyl = nejistá předpověď. Appka navíc ví, jak se které modely trefovaly za poslední měsíc (historii si dohledá z archivu hned, není potřeba čekat), a trefnějším dává vyšší váhu — detail najdeš v rozbalovacím řádku „Z čeho předpověď vychází" úplně dole.</p><p><b>ČHMÚ ALADIN</b> je model, kterým počítá předpovědi český hydrometeorologický ústav, a s krokem 1 km je z celé směsi nejjemnější (ICON-D2 má 2,2 km). Pro Česko má proto nakrátko jednu z nejvyšších vah. Počítá na tři dny dopředu, dál ho vystřídají globální modely.</p><p>Váhy se počítají <b>jako při vyrovnání měření: 1/σ²</b> ze skutečně změřené chyby zdroje — zdroj dvakrát přesnější má čtyřnásobnou váhu, ne o třetinu vyšší. Odlehlé zdroje se navíc <b>vylučují</b>: když jeden model tvrdí o pět stupňů něco jiného než všichni ostatní, do výsledku nejde vůbec (v seznamu zdrojů je pak přeškrtnutý). Hledá se to přes medián a MAD, ne přes průměr a směrodatnou odchylku — v těch se odlehlá hodnota sama schová. U srážek se nevylučuje nic, tam by vydatná přeháňka vypadala jako odlehlá hodnota, i když je pravdivá. Kde appka zná <b>systematickou chybu</b> modelu, tam ji rovnou <b>odečte</b>: model, který v tomhle místě dává trvale o stupeň víc, se srovná, ne jen odváží dolů.</p><p><b>Ensemble</b> je průměr ze všech běhů jednoho modelu (ECMWF 51 běhů, ICON-D2 dvacet) — bývá přesnější než jediný běh, protože se náhodné chyby vyruší. Pro Česko je nejcennější ICON-D2 s krokem 2 km. Ensembly se stahují nejvýš jednou za hodinu, ať nepálí mobilní data.</p><p>Aby vážený průměr nelhal, počítají se zdroje po <b>rodinách</b>: ICON-D2, ICON-EU a jejich ensembly jsou pořád jeden model DWD, takže se nejdřív zprůměrují mezi sebou a do celku vstoupí jedním hlasem. Jinak by měl jeden ústav několikanásobnou váhu a „Shoda zdrojů" by hlásila jistotu, která tam není.</p><p>Teploty se opravují podle <b>skutečné výšky</b> bodu z výškopisu DMR 5G: model počítá s výškou své sítě, a když jsi o 200 m výš, je to samo o sobě 1,3 °C rozdílu. U <b>srážek</b> se místo průměru bere medián (aby se ostrá přeháňka nerozmazala na mrholení) a vedle něj se ukazuje i nejdeštivější varianta — výstraha na déšť vychází i z ní, ať se riziko neschová. Váhy modelů se počítají zvlášť pro dosah <b>do 6 hodin</b> a zvlášť dál.</p><p><b>ČHMÚ</b> je jediná hodnota na obrazovce, která není předpověď, ale <b>skutečné měření</b> z nejbližší profesionální stanice (je jich 758, takže obvykle do pár kilometrů) — teplota, vlhkost, tlak, vítr, srážky. Podle něj se zároveň poměřuje, jak se který model trefil. ČHMÚ data zveřejňuje se zhruba hodinovým zpožděním, proto starší měření dostane v celkovém odhadu menší váhu. Funguje jen v Česku a jen když je dostupné firemní API (přes ně se data stahují — opendata.chmi.cz nejde volat přímo z prohlížeče).</p><p>Kolečkem se <b>šipkou</b> vpravo nahoře si předpověď kdykoli vynutíš znovu — stáhne se všechno včetně ensemblů a nových snímků radaru. Jinak se počasí obnovuje samo každých 15 minut, dokud je nástroj otevřený.</p><p>Karta <b>Kdy začne pršet</b> je na krátko to nejpřesnější, co appka umí: prvních dvě hodiny nejdou z modelu, ale z <b>radaru</b> (produkt DWD, 1 km, krok 5 minut) — radar vidí skutečné srážkové pole a jen ho posouvá, takže na takhle krátko porazí každý model. Dál pokračují modely <b>po 15 minutách</b>, aby se dvacetiminutová přeháňka neztratila v hodinovém průměru. V hlavičce je přímo „Déšť za 25 min", sloupečky pod tím jsou intenzita v mm/h (světlejší = z modelu, plné = z radaru; podržením se ukáže čas a hodnota). Radar má omezené pokrytí — na východní Moravě už mřížka DWD nedosáhne a karta jede jen z modelů, což si sama napíše. Radar umí říct „prší", ale ne sám „neprší", takže suchou předpověď vždycky potvrzují i modely.</p><p>Výstrahy na <b>nárazy větru</b> vycházejí z ensemblů, ale ne z jejich průměru — bere se devátý decil (P90), tedy nejhorší desetina běhů. Stativ s přístrojem se totiž pokládá v tom jednom nepříznivém scénáři, ne v průměru scénářů, a průměr by takový náraz zamázl.</p><p><b>Srážkový radar</b> ukazuje animovaně, jak se srážkové mraky pohybují (~70 min zpět + 30 min výhled). Mapou radaru jde posouvat i přibližovat (tlačítka +/− a ⌖ zpět na tvoje místo), posuvníkem si přehraješ jednotlivé snímky ručně. Tlak je přepočtený na nadmořskou výšku místa (v závorce i na moře) a u deště je vedle pravděpodobnosti i množství v mm.</p><ol><li>Bez zadání ukazuje počasí ve tvé poloze.</li><li>Ikonou <b>špendlíku</b> vybereš místo klepnutím do mapy — mapa zůstane ovladatelná, takže si ji nejdřív posuň a přibliž na zakázku, kam teprve pojedeš, a pak klepni.</li><li>Do pole nahoře můžeš místo taky vyhledat podle názvu.</li></ol><p>Upozornění hlídají, co vadí v terénu: bouřka a déšť do 3 h, vítr nad 8 m/s (stativ, výtyčka), mráz a vedro. Poslední stažená předpověď se pamatuje i offline.</p>' } },
        { k: 'slunce', verb: 'Zjistit podmínky', vl: 'Slunce a světlo', vh: 'protisvětlo, soumrak', keys: 'slunce svetlo zapad vychod soumrak stin protisvetlo oslneni tma azimut zlata hodina',
          help: { t: 'Slunce a světlo', h: '<p>Kolik zbývá denního světla a co s tím v terénu: východ, západ, konec soumraku, azimut a výška slunce, délka stínu a hodiny, kdy budeš mít slunce v ose záměry.</p><ol><li><b>Do západu zbývá…</b> — podle tempa dneška (kolik bodů/h jsi dnes zaměřil) odhadne, kolik bodů ještě stihneš.</li><li>Zadej <b>výšku svislice</b> (výtyčka, sloup) a uvidíš délku stínu — použitelné pro kontrolu směru i pro fotodokumentaci.</li><li>Zadej (nebo vezmi z kompasu) <b>azimut záměry</b> — appka vypíše hodiny, kdy bude slunce nízko v ose a neuvidíš do displeje ani na hranol.</li></ol><p>Vše se počítá offline (NOAA, časy ±1 min), azimuty k zeměpisnému severu. Stín platí pro vodorovný terén. Kontrola kompasu podle slunce je samostatné tlačítko dole.</p>' } },
        { k: 'dronview', verb: 'Zjistit podmínky', vl: 'Dronové zóny', vh: 'omezení vzdušného prostoru (ŘLP)', keys: 'dron drony zony letani omezeni vzdusny prostor uas dronview rlp', net: 1,
          help: { t: 'Dronové zóny (DronView)', h: '<p>Otevře oficiální mapu omezení letového provozu ŘLP ČR (DronView) — bezletové zóny, CTR letišť, omezené prostory.</p><p>Před letem s dronem na zakázce zkontroluj, jestli v místě smíš létat a v jaké výšce. Vyžaduje internet.</p>' } },

        // ── Katastr a podklady ──────────────────────────────────────────
        { k: 'openKatastr', verb: 'Katastr a podklady', vl: 'Katastr — kde právě stojím', keys: 'katastr parcela kn nahlizeni kde stojim mapa cuzk', net: 1, base: 1,
          help: { t: 'Katastr (zde stojím)', h: '<p>Otevře katastrální mapu na tvé aktuální pozici ve zvoleném zdroji (Mapy.cz, iKatastr, Geoprohlížeč ČÚZK — nastavíš v Nastavení → Data).</p><p>Hodí se pro rychlé zjištění parcelního čísla a hranic tam, kde stojíš.</p>' } },
        { k: 'cadastre-vector', cat: 'Katastr a data', verb: 'Katastr a podklady', vl: 'Parcely do mapy a do AR', keys: 'katastr vektor hranice parcely dxf import mapa kn', net: 1,
          help: { t: 'Katastr — parcely', h: '<p>Z katastru dělá <b>dotazovatelná data</b>, ne jen obrázek jako WMS: polygony parcel z ČÚZK stažené do telefonu, takže fungují i bez signálu.</p><ol><li>Na místě stáhni parcely v okolí (potřebuje jednou internet) — pak už drží offline v zakázce.</li><li>Appka řekne, <b>na které parcele stojíš</b>: číslo, výměra, druh pozemku a vzdálenost k nejbližší hranici.</li><li>Hranice se kreslí <b>v mapě i v AR kameře</b>.</li><li><b>Navigace na nejbližší lomový bod</b> hranice ho uloží jako bod a zvýrazní; podle něj pak hledáš mezník.</li></ol><p>Zdroj: prohlížecí služba RÚIAN ČÚZK, vrstva Parcela (© ČÚZK). Hranice z KN mají svou přesnost danou kódem kvality — <b>nejsou vytyčením</b> a v digitalizovaných mapách se od skutečnosti liší i o metry. Nouzově jde načíst parcely z GeoJSON souboru.</p>' } },
        { k: 'cadastre-area', verb: 'Katastr a podklady', vl: 'Stáhnout body z výřezu mapy', keys: 'stahnout body vyrez oblast okoli bodove pole import mapa', net: 1,
          help: { t: 'Stáhnout body z výřezu mapy', h: '<p>Hromadný import bodů bodových polí z ČÚZK: místo hledání bodu po bodu si tahem vybereš celý obdélník území a body v něm přidáš najednou.</p><ol><li>Otevři nástroj a <b>tahem po mapě</b> vyznač obdélník.</li><li>Appka stáhne body bodových polí uvnitř a nabídne je k přidání do zakázky.</li><li>Potvrď — body pak fungují offline, včetně AR a navigace.</li></ol><p>Vyžaduje internet a dostupnost služby ČÚZK; nevybírej moc velké území naráz. Data © ČÚZK.</p>' } },
        { k: 'parcela', cat: 'Katastr a data', verb: 'Katastr a podklady', vl: 'Parcela — geometrie a dělení', keys: 'parcela geometrie deleni vymera obvod smerniky dily',
          help: { t: 'Parcela / dělení', h: '<p>Geometrie parcely počítaná přímo v rovinných S-JTSK souřadnicích (Gaussův vzorec — v ČR správný způsob výpočtu výměr) a <b>dělení pozemku</b> na zadanou výměru.</p><ol><li>Postav polygon: klepáním do mapy, z bodů zakázky, zadáním Y a X, nebo obcházením z GPS.</li><li>Dostaneš <b>výměru, obvod</b> a tabulku hranice — délka a směrník každé strany v gonech i stupních.</li><li>Dělení: <b>rovnoběžně s vybranou hranou</b>, <b>přímkou z vybraného vrcholu</b>, nebo <b>na N stejných dílů</b>. Zadáš cílovou výměru a dělicí čára se dopočítá.</li><li>Vypočtené lomové body jde uložit do zakázky a rovnou je vytyčit.</li></ol><p>Výsledek je návrh do terénu, ne geometrický plán — ten dělá úředně oprávněný zeměměřický inženýr. Dělení počítá spolehlivě u konvexních a běžných nepravidelných parcel.</p>' } },
        { k: 'hodinky-parovani', cat: 'Katastr a data', verb: 'Před výjezdem', vl: 'Hodinky Garmin', vh: 'body z hodinek a zpátky', keys: 'hodinky garmin forerunner fenix watch parovani synchronizace body zapesti connect iq', net: 1,
          help: { t: 'Hodinky Garmin', h: '<p>Připojí aplikaci v hodinkách (Forerunner 255) k <b>aktuální zakázce</b>. Body naměřené na hodinkách se pak objeví tady mezi vlastními body a body odsud uvidíš na hodinkách.</p><ol><li>Klepni na <b>Vygenerovat kód</b> — dostaneš šest znaků, které platí 10 minut a použijí se jednou.</li><li>Kód opiš v mobilní aplikaci <b>Garmin Connect</b>: Zařízení → Connect IQ → AR Geodet → Nastavení → „Párovací kód z mobilu“.</li><li>Na hodinkách dlouze podrž <b>↑</b> a dej <b>Synchronizovat s mobilem</b>. Spáruje se, nahraje naměřené a stáhne okolí.</li></ol><p><b>Proč kód a ne přihlášení:</b> hodinky nemají klávesnici, takže se přihlásit nemůžou. S telefonem navíc nemluví přímo — to by chtělo nativní doprovodnou aplikaci a tahle appka je web. Data proto putují oklikou přes server: hodinky ↔ Cloudflare Worker ↔ appka. V terénu to funguje, dokud je telefon poblíž (hodinky si přes něj berou tunel k síti).</p><p>Do hodinek jde vždy jen <b>20 nejbližších bodů</b> — mají paměť v řádu stovek kB a celá zakázka by se do nich nevešla. Číslování si hodinky rezervují po blocích, aby offline nevznikly dva body se stejným číslem.</p><p><b>Přesnost bodů z hodinek je v jednotkách metrů</b> a údaj ±X m u nich je rozptyl vzorků, ne střední chyba. Na nalezení bodu to stačí, na vytyčení ne.</p>' } },
        { k: 'project-import', cat: 'Katastr a data', verb: 'Katastr a podklady', vl: 'Import projektu', vh: 'DXF, situace', keys: 'import projekt oblast stazeni csv dxf soubor nahrat', base: 1,
          help: { t: 'Import projektu (DXF)', h: '<p>Načtení projektu do terénu: výkres DXF v S-JTSK (body, čáry, polylinie, texty, kružnice) uvidíš <b>v mapě i v AR kameře</b> a můžeš z něj vytyčovat.</p><ol><li>Vyber soubor DXF. Poradí si s kladným geodetickým i záporným CAD zápisem souřadnic.</li><li>Jednotlivé <b>vrstvy výkresu</b> si zapneš a vypneš, ať v terénu nekoukáš na všechno naráz.</li><li>U lomového bodu klepni <b>Vytyčit</b> — uloží se jako bod zakázky a appka na něj navádí šipkou; nebo použij <b>Přenést vše do bodů zakázky</b>.</li><li>Místo DXF jde podložit i <b>rastr</b> (foto nebo sken situace) — georeferencuješ ho dvěma body a leží poloprůhledně nad mapou.</li></ol><p>Návrh se ukládá per zakázka, takže po restartu je zpátky. Výkres musí být v S-JTSK — výkres v místní soustavě nejdřív usaď nástrojem Lokalizace (Helmert).</p>' } },
        { k: 'geo-overlay', cat: 'Katastr a data', verb: 'Katastr a podklady', vl: 'Podložit plán do mapy', vh: 'georeference obrázku', keys: 'podklad georeference obrazek plan situace vykres overlay',
          help: { t: 'Vlastní podklad', h: '<p>Vlastní plán pod mapu: situace, geometrický plán, sken starého výkresu nebo podklad od projektanta. Po georeferencování navádíš podle <b>svého</b> podkladu, ne jen podle ČÚZK.</p><ol><li>Vyber obrázek (foto nebo sken).</li><li>Označ vlícovací body: klepneš do obrázku a k bodu doplníš skutečné souřadnice — ručně S-JTSK Y/X, z aktuální GPS, nebo výběrem existujícího bodu.</li><li><b>2 body</b> = podobnostní (Helmert) transformace: posun, otočení, měřítko. <b>3 a víc</b> = afinní transformace metodou nejmenších čtverců, u každého bodu uvidíš <b>reziduum</b> — velké reziduum značí špatně trefený bod.</li><li>Průhlednost si nastavíš; podklad drží i při otočené mapě.</li></ol><p>Obrázek se ukládá per zakázka do telefonu. Sken zdeformovaného nebo pokrčeného papíru žádná transformace nenarovná — vlícovací body volej co nejdál od sebe a po rozích.</p>' } },
        { k: 'utility-networks', verb: 'Katastr a podklady', vl: 'Podzemní sítě', keys: 'site podzemni vedeni inzenyrske gml kabel plyn voda',
          help: { t: 'Podzemní sítě', h: '<p>„Rentgen do země": vedení inženýrských sítí (voda, plyn, elektro, kanalizace…) zobrazené v mapě a v AR pod nohama, s barvami dle druhu sítě.</p><ol><li>Naimportuj data od správce sítě (DXF/GML z vyjádření).</li><li>V AR uvidíš trasy vedení promítnuté na terén, s hloubkou, pokud je v datech.</li></ol><p>Pozor: poloha sítí v podkladech bývá orientační — před výkopem vždy platí vytyčení správcem.</p>' } },
        { k: 'job-transfer', verb: 'Katastr a podklady', vl: 'Poslat nebo načíst zakázku', keys: 'prenos zakazky export import argeo sdileni telefon', net: 1,
          help: { t: 'Poslat/načíst zakázku', h: '<p>Přenos celé zakázky mezi zařízeními souborem <b>.argeo</b> (body, nastavení, náčrty): pošli si ji mailem, messengerem nebo přes sdílení.</p><ol><li><b>Poslat:</b> vyber zakázku → vytvoří se soubor .argeo ke sdílení.</li><li><b>Načíst:</b> otevři přijatý soubor / vyber ho zde — zakázka se přidá vedle stávajících (nic nepřepíše bez potvrzení).</li></ol>' } },
        { k: 'hidden-points', verb: 'Katastr a podklady', vl: 'Skryté body', keys: 'skryte body obnovit zobrazit schovane',
          help: { t: 'Skryté body', h: '<p>Přehled bodů skrytých tlačítkem „Skrýt tento bod z AR". Klepnutím na <b>Zobrazit</b> vrátíš jednotlivý bod, nebo obnovíš všechny najednou.</p><p>Skrytí platí do restartu appky — po novém spuštění jsou body zase viditelné.</p>' } },

        // ── Před výjezdem ───────────────────────────────────────────────
        { k: 'brifink', verb: 'Před výjezdem', vl: 'Dnešek v terénu', vh: 'souhrn na ráno', keys: 'brifink dnesek souhrn rano prehled dne pocasi svetlo terminy', net: 1,
          help: { t: 'Dnešek v terénu', h: '<p>Ranní brífink na jedné kartě: co tě dnes v terénu čeká, bez klikání po čtyřech nástrojích. Otevře se sám při <b>prvním spuštění dne</b> (vypneš přepínačem dole v kartě) nebo kdykoli touto dlaždicí.</p><ol><li><b>Počasí dnes:</b> teploty, kdy má pršet, vítr, východ–západ slunce a kolik zbývá světla (offline ukáže poslední stažené).</li><li><b>GNSS dnes:</b> z uložených drah družic spočte nejlepší a nejhorší okno dne (PDOP) + Kp index — při geomagnetické bouři GNSS zlobí.</li><li><b>Monitoring a zpravodaj:</b> body po termínu přeměření a titulek dnešního vydání.</li></ol><p>Okna GNSS potřebují stažené dráhy (nástroj GNSS satelity) a polohu; počasí a Kp potřebují při prvním stažení internet.</p>' } },
        { k: 'checklist', verb: 'Před výjezdem', vl: 'Co s sebou', keys: 'checklist co s sebou baleni vybaveni seznam rano nezapomen vzit',
          help: { t: 'Co s sebou', h: '<p>Ranní balicí seznam, který se skládá sám: základ + vybavení podle <b>typu práce</b> zakázky + položky navíc podle <b>dnešního počasí</b> (mráz → náhradní baterie, déšť → sáček na telefon, vedro → voda, vítr → zátěž na stativ).</p><ol><li>Ráno otevři dlaždici a odškrtávej, co máš v autě.</li><li><b>Přidat položku</b> uloží tvoje vlastní věci trvale (klíč od brány…).</li><li>Odškrtání platí na dnešní den a tuhle zakázku — zítra je seznam znovu čistý.</li></ol><p>Aby se doplnily položky kvůli počasí, musí být stažené <b>Počasí</b>. Typ práce nastavíš v Nástrojích (jednoduchý režim).</p>' } },
        { k: 'bezpecnost', verb: 'Před výjezdem', vl: 'Bezpečnost a rizika', keys: 'bezpecnost bozp riziko vedro pitny rezim bourka blesk vesta soumrak mraz vitr sos poloha pomoc',
          help: { t: 'Bezpečnost', h: '<p>Bezpečnostní panel pro práci venku o samotě. Nahoře je stav: kde jsem (WGS84 i S-JTSK) a JAK STARÁ ta poloha je, přesnost GPS, datové připojení, baterie a komu se poloha pošle.</p><ol><li><b>Tísňová linka 112</b> — tlačítko se musí <b>držet 2 s a pustit</b> (vidíš odpočet). Pustíš dřív nebo mimo tlačítko: nic se nestane. Je to pojistka proti náhodnému doteku v kapse.</li><li><b>155 / 150 / 158</b> — první ťuknutí číslo jen natáhne, druhé volá.</li><li>Pod tím dlaždice: poslat polohu, SMS s polohou, zkopírovat, volat kontaktu. <b>Nouzové kontakty</b> zůstávají jen v tomhle telefonu.</li><li><b>Rizika dneška</b> (bouřka, vedro, mráz, vítr, blížící se tma) se plní z posledního staženého počasí a z časů soumraku. Přepínačem zapneš tiché připomínky, „Ztišit na dnes" je jeden tap.</li></ol><p>Appka sama nikam nic neposílá a nikoho nevolá — jen otevře vytáčení, zprávy nebo sdílení; jestli hovor proběhl nebo SMS odešla, nepozná, a proto to netvrdí. Baterie se na iPhonu hlásí jako nedostupná (Safari ji nedává). Hodnoty u rizik jsou orientační doporučení, ne citace předpisů (NV 361/2007 Sb.). Připomínky běží jen když je appka otevřená.</p>' } },
        { k: 'kde-je', verb: 'Před výjezdem', vl: 'Kde co mám', vh: 'báze, stativ, materiál — i auto', keys: 'auto parkovani kde stoji baze stativ material najit zpatky navigace znacka',
          help: { t: 'Kde co mám', h: '<p>Jedním tapem si označíš, kde máš bázi, stativ, materiál nebo auto — a pak tě to tam dovede: vzdálenost, azimut a šipka otočená podle kompasu.</p><ol><li>Než odejdeš od auta, klepni na <b>🚗 Auto</b> (nebo Báze / Stativ / Materiál / Vlastní).</li><li>V seznamu vidíš živě vzdálenost a šipku — drž telefon před sebou jako v AR.</li><li><b>Zobrazit v mapě</b> vykreslí značky do hlavní mapy; <b>Uklidit staré</b> smaže značky starší dvou dnů.</li></ol><p>Značky nejsou měřená data: neukládají se mezi body zakázky ani do exportů a protokolů. U báze a stativu se pamatuje přesnost fixu — ber ji jako poloměr, ve kterém hledat.</p>' } },

        // ── Firma a papíry ──────────────────────────────────────────────
        { k: 'zmenit-zakazku', cat: 'Pomůcky', verb: 'Firma a papíry', vl: 'Změnit zakázku', vh: 'přepnout se na jinou práci bez restartu', keys: 'zakazka zakazky prepnout zmenit projekt praca stavba jina zakazka prepnuti vybrat zakazku zmena zakazky',
          help: { t: 'Změnit zakázku', h: '<p>Přepne appku na jinou zakázku rovnou z Nástrojů. Dřív se to dalo jen na úvodní obrazovce nebo v Nastavení → Data, takže se člověk musel proklikat pryč od rozdělané práce.</p><ol><li>Seznam ukazuje zakázky, do kterých máš přístup — u té otevřené je fajfka a počet bodů.</li><li>Klepnutím se přepneš: načtou se body, poznámky i nastavení té zakázky a překreslí se mapa i AR.</li><li><b>+ Nová zakázka</b> otevře stejné zakládání jako na úvodní obrazovce (včetně šablon).</li></ol><p>Rozdělaná práce se neztrácí — zůstane uložená v zakázce, ze které odcházíš. Ve firemním režimu se drží oprávnění: komu admin přidělil jen některé zakázky, vidí a přepne jen ty.</p>' } },
        { k: 'dochazka', verb: 'Firma a papíry', vl: 'Docházka', keys: 'dochazka prichod odchod pracovni doba hodiny smena',
          help: { t: 'Docházka', h: '<p>Příchod a odchod na zakázce s razítkem času a GPS polohy — podklad pro výkaz odpracovaných hodin.</p><ol><li>Na místě klepni <b>Příchod</b> — doplníš stavbu a s kým tam jsi (nepovinné, příště se předvyplní).</li><li>Na konci klepni <b>Odchod</b> a napiš, co se dělalo.</li><li>Když odchod zapomeneš, doplníš ho při dalším startu (nebo ho opraví admin).</li><li>Administrace firmy páruje směny a počítá hodiny; stavba, parta i činnost jsou v rozpisu, CSV i tisku.</li></ol><p>Funguje i offline — záznamy se odešlou, až bude signál.</p>' } },
        { k: 'firma-chat', verb: 'Firma a papíry', vl: 'Firemní chat', keys: 'chat zpravy firma kolegove komunikace vzkaz psani', net: 1,
          help: { t: 'Firemní chat', h: '<p>Zprávy mezi lidmi ve firmě přes firemní cloud — domluva z terénu bez hledání telefonního čísla.</p><ol><li>Napiš zprávu; ostatní ji uvidí do pár sekund.</li><li>Tlačítkem <b>Poslat body</b> pošleš vybrané body ze zakázky, příjemce je přidá jedním klepnutím.</li><li>Nepřečtené hlásí odznak na dlaždici.</li></ol><p>Vyžaduje přihlášení do firmy a internet.</p>' } },
        { k: 'vysilacka', verb: 'Firma a papíry', vl: 'Vysílačka', vh: 'kde je kolega, rychlé zprávy, hlídání pádu', keys: 'vysilacka poloha kolegove tym kde jsou sdileni pozice',
          help: { t: 'Vysílačka', h: '<p>Měřič u přístroje a figurant s výtyčkou: kde je kolega, co zrovna dělá a co dělat, když se něco stane. Tři věci na jednom místě.</p><ol><li><b>Rychlá zpráva</b> jedním ťuknutím — „Můžu měřit“, „Hledám bod“, „Stavím stativ“… Odejde do firemního chatu a zároveň se ukáže jako tvůj stav u polohy.</li><li><b>Kde je kdo</b> — vzdálenost, šipka podle kompasu a <b>stáří</b> té polohy. Tlačítkem <b>Ukázat v mapě</b> je uvidíš i v mapě.</li><li><b>Vysílat moji polohu</b> zapneš přepínačem; posílá se poslední známý bod (ne stopa) a jen dokud je appka otevřená.</li><li><b>Hlídat pád (Man Down)</b> — volný pád nebo tvrdý náraz a pak klid = odpočet 30 s. Když ho nezrušíš, odejde kolegům zpráva se souřadnicemi a nabídne se SMS a linka 112.</li></ol><p><b>Poctivá omezení:</b> hlídání i vysílání běží <b>jen když je appka vepředu</b> (proto se drží rozsvícený displej) — telefon zamčený v kapse prohlížeč uspí. Není to náhrada za SOS zařízení. Appka sama nikam nevolá ani neposílá SMS, jen otevře vytáčení a zprávy. „Kde je kdo“ potřebuje cloudovou firmu, internet a server s endpointem <b>/pos</b>; na starším serveru se to napíše a zbytek funguje dál.</p>' } },
        { k: 'ucty-firma', verb: 'Firma a papíry', vl: 'Firma a účty', keys: 'firma ucty uzivatele role opravneni sprava zamestnanci prihlaseni',
          help: { t: 'Firma a účty', h: '<p>Správa firmy: uživatelé, role a oprávnění, přehled užívání a docházky, zálohy.</p><ol><li><b>Uživatelé:</b> zakládání účtů, PIN, role (admin / geodet / pomocník) a co kdo smí.</li><li><b>Přehled:</b> kolik bodů kdo naměřil, na jakých zakázkách a kdy.</li><li><b>Zařízení:</b> připojení dalšího telefonu QR kódem od admina.</li></ol><p>Bez cloudu funguje lokálně na jednom zařízení; s cloudem se účty sdílejí mezi telefony.</p>' } },
        { k: 'kniha-jizd', verb: 'Firma a papíry', vl: 'Kniha jízd', keys: 'kniha jizd cestak kilometry km naklady cestovni nahrady tachometr vozidlo ucetni',
          help: { t: 'Kniha jízd', h: '<p>Cesťák navázaný na zakázky: kdy, odkud kam, kolik kilometrů a kvůli které zakázce. Měsíční součty a export CSV pro účetní.</p><ol><li>Před odjezdem klepni <b>Odjíždím</b> (můžeš zadat stav tachometru), po příjezdu <b>Přijel jsem</b>.</li><li>Bez tachometru se km <b>odhadnou</b> ze vzdušné vzdálenosti ×1,3 — takové jízdy jsou v seznamu označené jako odhad.</li><li><b>Zapsat ručně</b> doplní jízdu zpětně, <b>Export CSV</b> uloží vybraný měsíc, <b>Vozidlo a sazba</b> nastaví SPZ a Kč/km.</li></ol><p>Appka nezná zákonné náhrady ani spotřebu — sazbu Kč/km zadáváš ty a jde jen o dopočet. Data jsou pouze v tomto telefonu a nejsou součástí zálohy zakázky, takže si CSV pravidelně exportuj.</p>' } },
        { k: 'moje-aktivita', verb: 'Firma a papíry', vl: 'Moje aktivita', vh: 'kolik jsem ušel, co používám, co schovat', keys: 'aktivita statistika prehled kroky krokomer kilometry vyskove metry nastoupano cas souhrn dne kolik jsem udelal pouzivani nastroju skryt nepouzivane',
          help: { t: 'Moje aktivita', h: '<p>Přehled vlastní práce: kolik času jsi měl appku otevřenou, kolik jsi ušel a nastoupal, kolik kroků, kolik bodů jsi přidal a <b>který nástroj kolikrát a jak dlouho</b> jsi používal. K tomu shrnutí dne a posledních 7 dní.</p><ol><li>Nic se nezapíná — počítá se to samo od startu appky (vypnout jde přepínačem <b>Měřit moji aktivitu</b> dole v okně).</li><li>Sekce <b>Do čeho jsem nešáhl</b> vypíše nástroje, které jsi nikdy neotevřel. Tlačítkem <b>skrýt</b> jejich dlaždici schováš z Nástrojů i ze seznamu úkonů — nic se nemaže, hledání je najde dál a <b>Skryté nástroje</b> je vrátí.</li><li>U často používaných nástrojů je ☆ — přidá je do <b>★ Oblíbených</b> nahoru v Nástrojích.</li><li><b>Export CSV</b> vytáhne den po dni pro vlastní evidenci.</li></ol><p>Čísla jsou přehled, ne měřický protokol: vzdálenost a výškové metry pocházejí z GPS mobilu (výška se vyhlazuje a počítá se až schod nad 3 m), počítá se jen chůze — při rychlosti nad ~12 km/h se nesčítá, aby jízda autem nedělala kilometry. Kroky jsou odhad z ušlé vzdálenosti, dokud nezapneš krokoměr z akcelerometru. Data zůstávají v tomhle telefonu a do zálohy zakázky nepatří.</p>' } },

        // ── Příručka a výpočty ──────────────────────────────────────────
        { k: 'predpisy', verb: 'Příručka a výpočty', vl: 'Předpisy a odchylky', keys: 'predpisy vyhlaska odchylky kody lhuty tahak normy trida presnosti',
          help: { t: 'Předpisy & odchylky', h: '<p>Offline tahák z katastrálních předpisů: mezní odchylky, kódy kvality, lhůty a paragrafy. Kurátorovaný obsah s uvedeným zdrojem, hledej fulltextem.</p>' } },
        { k: 'postupy', cat: 'Pomůcky', verb: 'Příručka a výpočty', vl: 'Postupy měření', keys: 'postupy navody checklisty pracovni kroky jak na',
          help: { t: 'Postupy měření', h: '<p>Tahák krok za krokem pro běžné metody: rajón, volné stanovisko, tachymetrie, polygonový pořad, technická nivelace, GNSS-RTK…</p><p>Vychází z oficiálních předpisů (Návod pro obnovu katastrálního operátu, katastrální vyhláška). U limitů je vždy uveden zdroj.</p>' } },
        { k: 'openDictModal', verb: 'Příručka a výpočty', vl: 'Slovník pojmů', keys: 'slovnik pojmy zkratky vyznam terminologie',
          help: { t: 'Slovník', h: '<p>Geodetický slovník pojmů a zkratek (TB, ZhB, Bpv, ZPMZ, GP…). Hledej v poli nahoře; vlastní pojmy si můžeš přidat dole.</p>' } },
        { k: 'openCalcModal', verb: 'Příručka a výpočty', vl: 'Kalkulačka', keys: 'kalkulacka vypocet prevod gon stupne uhly plocha',
          help: { t: 'Kalkulačka', h: '<p>Geodetické výpočty: směrník a délka ze souřadnic, rajón, protínání, převody úhlů (°/gon), redukce délek do S-JTSK a další.</p><p>Souřadnice zadávej v S-JTSK (kladné Y, X). Výsledky lze rovnou uložit jako bod.</p>' } },

        // ── bez slovesa (spadnou do „Další nástroje“ / nejsou dlaždice) ─────
        { k: 'agPosFromMap', notile: 1,
          help: { t: 'Poloha z mapy', h: '<p>V lese, v úzké ulici a mezi paneláky je GPS telefonu nejslabší — odrazy od listí a fasád dělají chyby v metrech a průměrování je <b>neodstraní</b>. Přitom sám často přesně vidíš, kde stojíš: pod tebou je na ortofotu roh domu, obruba, kanál nebo rozvětvení cesty. Tímhle si polohu odečteš z mapy a appka ji začne používat místo GPS.</p><ol><li>Otevři <b>Mapa a vrstvy → Poloha z mapy</b>. Nabídne se zapnutí <b>ortofota</b> — na něm se poznáš nejlíp.</li><li><b>Přibliž</b> mapu co nejvíc (přesnost se počítá z měřítka) a klepni přesně na místo, kde stojíš.</li><li>Značka polohy zjantarová, kruh přesnosti se ocerchuje a v upozorněních visí štítek <b>Poloha z mapy</b>. Od té chvíle z ní jedou AR šipky, vzdálenosti, azimuty i „Z průměru GPS".</li><li>Zrušíš ji štítkem <b>Zrušit</b> nebo znovu tímtéž tlačítkem (<b>Zpět na GPS</b>).</li></ol><p>Přesnost se nelže: bere se z měřítka mapy (metry na pixel × trefa prstem) a nikdy nejde pod <b>±1 m</b> — ortofoto má svoji vlastní chybu a vlastní stanoviště se v něm taky nepozná lépe. Když z odečtu vyjde horší číslo, než hlásí GPS, appka to řekne a poradí přiblížit.</p><p>Ruční poloha se <b>sama zruší</b>, jakmile odejdeš o víc než 25 m (pozná se to na posunu surových GPS fixů — ten chůzi ukáže spolehlivě, i když je absolutní poloha vedle), a <b>nepřežije restart</b> appky. Obojí schválně: připnutá poloha z jiné části zakázky by byla past.</p>' } },
        { k: 'auto-bezpeci', keys: 'auto bezpeci kde mam auto baze stativ material kniha jizd cestak kilometry bourka vedro mraz vitr tma sos rizika co s sebou balici seznam checklist rozcestnik', hub: 1,
          help: { t: 'Auto a bezpečí', h: '<p>Rozcestník věcí kolem měření — auto, kilometry a vlastní kůže. Dřív čtyři dlaždice roztroušené v Pomůckách:</p><ol><li><b>Kde mám auto</b>: označíš, kde stojí auto, báze, stativ nebo materiál, a pak tě tam navede vzdálenost se šipkou.</li><li><b>Kniha jízd</b>: cesťák navázaný na zakázky, měsíční součty, export CSV pro účetní.</li><li><b>Bezpečnost a rizika</b>: bouřka, vedro, mráz, vítr a blížící se tma; tiché připomínky a poslání vlastní polohy.</li><li><b>Co s sebou</b>: balicí seznam poskládaný podle typu práce a dnešního počasí.</li></ol><p>Nic z toho nejsou měřená data — do bodů zakázky, exportů ani protokolů se to nepromítá.</p>' } },
        { k: 'bod-vypoctem', keys: 'bod vypoctem novy vypocet rajon offset protinani smernik delka uhel konstrukce rozcestnik', hub: 1,
          help: { t: 'Bod výpočtem', h: '<p>Rozcestník pro vytvoření nového bodu z existujících bodů — podle toho, co umíš změřit:</p><ol><li><b>Rajón</b>: stojíš na známém bodě a máš směr + vodorovnou délku.</li><li><b>Offset bod</b>: odsazení od bodu o azimut/směrník a vzdálenost.</li><li><b>Protínání vpřed</b>: délku změřit nemůžeš — bod protneš záměrami ze dvou známých stanovisek.</li></ol><p>Jednotlivé metody najdeš i vyhledáváním („rajón", „offset", „protínání").</p>' } },
        { k: 'err-log', keys: 'protokol chyb log chyba diagnostika hlaseni', noverb: 1,
          help: { t: 'Protokol chyb', h: '<p>Když se v appce něco pokazí, chyba se sem tiše zapíše — appka je psaná tak, aby jeden nefunkční nástroj nezhodil zbytek, ale pak se v terénu nedá zjistit, co vlastně selhalo. Tady to zjistíš.</p><ol><li>Seznam je od nejnovější: čas, hláška a místo v kódu, kde to spadlo.</li><li><b>Kopírovat</b> vysype protokol jako text — vlož ho do hlášení o chybě.</li><li><b>Vymazat</b> seznam vyprázdní.</li></ol><p>Drží se posledních <b>40</b> záznamů, jen v tomhle telefonu; přežijí restart a přibalí se do zálohy. Záznam v protokolu neznamená ztracená data — ale stejná chyba, která se vrací, je stopa, kterou má smysl poslat.</p>' } },
        { k: 'gnss-signal', keys: 'gnss signal gps kvalita druzice satelity predikce semafor skore multipath obloha podminky', hub: 1,
          help: { t: 'Signál GNSS', h: '<p>Rozcestník kvality GPS: <b>Družice teď</b> (kolik jich je nad obzorem a jaká je geometrie), <b>Predikce signálu</b> (skyplot s maskou překážek — plánování měření u lesa či v zástavbě) a <b>Semafor místa</b> (skóre odrazů a stability na aktuálním místě).</p><p>Použij před přesnějším měřením — počkej si na lepší konstelaci nebo si stoupni jinam.</p>' } },
        { k: 'pocasi-svetlo', keys: 'pocasi svetlo slunce vychod zapad soumrak stin srazky dest radar vitr tlak gnss predpoved pdop kp brifink dnesek obloha podminky rozcestnik', hub: 1,
          help: { t: 'Počasí a světlo', h: '<p>Rozcestník všeho, co dnes udělá obloha — dřív to byly čtyři samostatné dlaždice vedle sebe:</p><ol><li><b>Počasí</b>: předpověď pro místo měření až z 33 zdrojů (v Česku i model ČHMÚ ALADIN 1 km a naměřená data ČHMÚ), karta „kdy začne pršet" z radaru, srážkový radar, vítr, tlak přepočtený do tvé nadmořské výšky.</li><li><b>Slunce a světlo</b>: východ, západ, konec soumraku, délka stínu a hodiny, kdy budeš mít slunce v ose záměry.</li><li><b>GNSS předpověď</b>: kdy dnes bude nejlepší geometrie družic (PDOP) a jestli nezlobí ionosféra (Kp index).</li><li><b>Dnešek v terénu</b>: ranní brífink, který tohle všechno shrne na jednu kartu.</li></ol><p>Jednotlivé nástroje najdeš dál i vyhledáváním („počasí", „slunce", „PDOP") a v pohledu <b>Úkony</b> pod „Zjistit podmínky" a „Před výjezdem".</p>' } },
        { k: 'prirucka', keys: 'prirucka predpisy postupy slovnik odchylky kody lhuty navody tahak pojmy zkratky', hub: 1,
          help: { t: 'Příručka', h: '<p>Offline tahák do terénu: <b>Předpisy &amp; odchylky</b> (mezní odchylky, kódy kvality, lhůty — s uvedeným zdrojem), <b>Postupy měření</b> (krok za krokem: rajón, volné stanovisko, nivelace, GNSS-RTK…) a <b>Slovník</b> (pojmy a zkratky).</p>' } }
    ];

    // ---- rejstřík a API ---------------------------------------------------------
    var BY = {};
    for (var i = 0; i < T.length; i++) { BY[T[i].k] = T[i]; }

    function get(k) { return (k && BY[k]) || null; }

    // Skupiny pro seznam úkonů ve tvaru, který čeká js/nastroje-ukony.js:
    // [{ t: 'Změřit', items: [{ k, l, h }] }] — pořadí skupin dle VERBS, pořadí
    // položek dle pořadí záznamů v T.
    function groups() {
        var byVerb = {}, out = [], j;
        for (j = 0; j < VERBS.length; j++) { byVerb[VERBS[j]] = { t: VERBS[j], items: [] }; }
        for (j = 0; j < T.length; j++) {
            var r = T[j];
            if (!r.verb || !byVerb[r.verb]) continue;
            var it = { k: r.k, l: r.vl || r.k };
            if (r.vh) it.h = r.vh;
            byVerb[r.verb].items.push(it);
        }
        for (j = 0; j < VERBS.length; j++) { if (byVerb[VERBS[j]].items.length) out.push(byVerb[VERBS[j]]); }
        return out;
    }

    // Klíče s návodem. Vrací je od NEJDELŠÍHO — dlaždice se poznává hledáním
    // klíče v textu `onclick` a kratší klíč umí být kusem delšího („pocasi“ je
    // uvnitř „agOpenPocasi“), takže na pořadí záleží.
    var HELP_KEYS = null;
    function helpKeys() {
        if (!HELP_KEYS) {
            HELP_KEYS = [];
            for (var j = 0; j < T.length; j++) { if (T[j].help) HELP_KEYS.push(T[j].k); }
            HELP_KEYS.sort(function (a, b) { return b.length - a.length; });
        }
        return HELP_KEYS;
    }

    window.AGReg = {
        all: function () { return T.slice(); },
        get: get,
        groups: groups,
        verbs: function () { return VERBS.slice(); },
        help: function (k) { var r = get(k); return (r && r.help) || null; },
        helpKeys: helpKeys,
        aliases: function (k) { var r = get(k); return (r && r.keys) || ''; },
        cat: function (k) { var r = get(k); return (r && r.cat) || ''; },
        isNet: function (k) { var r = get(k); return !!(r && r.net); },
        baseSet: function () {
            var out = [];
            for (var j = 0; j < T.length; j++) { if (T[j].base) out.push(T[j].k); }
            return out;
        },
        profiles: function () { return PROFILES.slice(); }
    };
})();
